import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useInView } from "react-intersection-observer";
import style from "./PresetListItem.module.scss";

const PresetListItem = ({ id, name, imageId }) => {
  const [isVisible, setIsVisible] = useState(false);
  const { ref, inView } = useInView({
    threshold: 0.2,
  });

  useEffect(() => {
    if (inView) {
      setIsVisible(true);
    }
  }, [inView]);

  return (
    <div ref={ref}>
      <Link
        style={imageId ? {} : {
          background: "linear-gradient(to bottom right, rgb(89, 107, 185), rgb(52, 163, 145))",
          padding: "10%",
        }}
        className={isVisible ? style.list_item : style.dfs}
        to={`/work/preset/${id}`}
      >
        {isVisible && imageId && <img src={imageId} alt={name} />}
        <span style={imageId ? {} : {
          fontSize: "20pt",
          color: "whitesmoke",
          textShadow: "0 0 10px white",
        }}>
          {name}
        </span>
      </Link>
    </div>
  );
};

export default PresetListItem;