import style from "./SharedPresetsListModule.module.scss";
import { Spin } from "antd";
import { Link } from "react-router-dom";
import { LikeFilled } from "@ant-design/icons";
import { useEffect } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faHeart } from "@fortawesome/free-solid-svg-icons";

const SharedPresetsListModule = ({
  presets = {
    presets: [],
  },
  loading,
}) => {
  return (
    <Spin className={style.loading} spinning={loading}>
      {!presets.length ? (
        <h1 className={style.nomore}>А всё, нету больше!</h1>
      ) : (
        <div className={style.grid_wrapper}>
          {presets.map((preset) => {
            return (
              <Link
                to={`/work/shared-presets/preset-preview/${preset.id}`}
                className={
                  preset?.presetImageUrl
                    ? style.grid_item
                    : `${style.grid_item} ${style.grid_item_noimg}`
                }
                key={preset.id}
              >
                {preset?.presetImageUrl ? (
                  <img src={preset.presetImageUrl} alt="Preset" />
                ) : (
                  <></>
                )}
                <div className={style.grid_item_info}>
                  <div className={style.info_name}>
                    <span>{preset.name}</span>
                  </div>
                  <div className={style.info_items}>
                    <FontAwesomeIcon
                      style={
                        preset.isLikedByMe
                          ? {
                              color: "red",
                            }
                          : {}
                      }
                      icon={faHeart}
                    />{" "}
                    {preset.likesCount}
                  </div>
                </div>
              </Link>
            );
          })}
        </div>
      )}
    </Spin>
  );
};

export default SharedPresetsListModule;
