import React, { useEffect, useRef, useState } from "react";
import ReactECharts from "echarts-for-react";
import { useParams } from "react-router-dom";
import { RecoilRoot, useRecoilState, useResetRecoilState } from "recoil";
import {
  controlElementChangesHistoryState,
  controlElementState,
} from "../atoms/RecordsStates";
import style from "../ControlElementHandler.module.scss"

const ChangesChart = () => {
  const { timeIndex } = useParams();
  const chartRef = useRef(null);
  const isMousePressed = useRef(false);
  const [points, setPoints] = useState([]); // Локальное состояние для точек
  const minTimeRef = useRef(null);
  const maxTimeRef = useRef(null);
  const [controlElement, setControlElement] =
    useRecoilState(controlElementState);
  const resetControlElement = useResetRecoilState(controlElementState);
  const [changesHistory, setChangesHistory] = useRecoilState(
    controlElementChangesHistoryState
  );
  const buttonRef = useRef(null);

    const maxTime = 180000;

  useEffect(() => {
    if (controlElement?.times?.length) {
      const currentIndex = Number(timeIndex);
      const currentTime = controlElement.times[currentIndex];
      if (!currentTime) {
        window.location.reload();
      }

      // Минимальное время текущего элемента
      minTimeRef.current = Math.min(
        ...currentTime.changes.map((item) => item.time)
      );
      // Определение максимального времени
      if (currentIndex < controlElement.times.length - 1) {
        // Если есть следующий элемент, берем его минимальное время
        const nextTime = controlElement.times[currentIndex + 1];
        maxTimeRef.current = Math.min(
          ...nextTime.changes.map((item) => item.time)
        );
      } else {
        // Если элемент последний, ставим 3 минуты (180000 мс)
        maxTimeRef.current = maxTime;
      }

      setPoints([...currentTime?.changes]);
    }
  }, [controlElement, timeIndex]); // Добавляем timeIndex в зависимости

  useEffect(() => {
    if (chartRef.current) {
      const echartsInstance = chartRef.current.getEchartsInstance(); // Получаем экземпляр echarts
      const zr = echartsInstance.getZr();

      const sortPoints = (points) => {
        return [...points].sort((a, b) => a.time - b.time);
      };

      const clampPoints = (points) => {
        const clamped = points.filter((item) => {
          return (
            item.time >= 0 &&
            item.time <= maxTimeRef.current &&
            item.value >= 0 &&
            item.value <= 127
          );
        });

        return clamped;
      };
      const mouseDown = (e) => {
        buttonRef.current = e.event.button;
        isMousePressed.current = true;
      };

      const mouseMove = (e) => {
        if (!isMousePressed.current || buttonRef.current !== 1) return;

        const pointInPixel = [e.offsetX, e.offsetY];
        const [x, y] = echartsInstance.convertFromPixel("grid", [
          pointInPixel[0],
          pointInPixel[1],
        ]);

        // Округляем значения до целых чисел
        const roundedX = Math.round(x);
        const roundedY = Math.round(y);

        // Обновляем локальное состояние с проверкой на дубликаты
        setPoints((prevPoints) => {
          // Проверяем, есть ли точка с таким же временем
          const existingPointIndex = prevPoints.findIndex(
            (item) => item.time === roundedX
          );
          if (roundedY > 127 || roundedY < 0) return prevPoints;
          if (existingPointIndex !== -1) {
            // Если точка с таким временем уже существует, обновляем её значение
            const updatedPoints = [...prevPoints];
            updatedPoints[existingPointIndex] = {
              time: roundedX,
              value: roundedY,
            };
            return updatedPoints;
          } else {
            // Если точки с таким временем нет, добавляем новую
            return [...prevPoints, { time: roundedX, value: roundedY }];
          }
        });
      };

      const mouseUp = (e) => {
        isMousePressed.current = false;

        // Фильтруем и сортируем точки перед передачей в onUpdate
        const sortedPoints = sortPoints(points);
        const clampedPoints = clampPoints(sortedPoints);
        buttonRef.current = null;
        setChangesHistory((prev) => [...prev, clampedPoints]);
      };

      const deletePoints = (e) => {
        if (buttonRef.current !== 2) return;
        const pointIndex = e.data[2]?.index;

        if (pointIndex !== undefined) {
          setPoints((prev) => {
            if (prev.length === 2) return prev;
            return prev.filter((item, index) => index !== pointIndex);
          });
        }
      };

      // Теперь можно взаимодействовать с zRenderer
      zr.on("mousedown", mouseDown);
      zr.on("mousemove", mouseMove);
      zr.on("mouseup", mouseUp);
      zr.on("contextmenu", (e) => {
        e.event.stopPropagation();
        e.event.preventDefault();
      });

      echartsInstance.on("mousemove", deletePoints);

      // Очистка событий при размонтировании
      return () => {
        zr.off("mousedown", mouseDown);
        zr.off("mousemove", mouseMove);
        zr.off("mouseup", mouseUp);
        echartsInstance.off("mousemove", deletePoints);
      };
    }
  }, [points, changesHistory]);

  useEffect(() => {
    if (!changesHistory.length) return;

    setPoints((prev) => [...changesHistory][changesHistory.length - 1]);
  }, [changesHistory]);

  return (
    <div className={style.changes_chart_wrapper}>
      <ReactECharts
        ref={chartRef}
        className={style.changes_chart}
        // style={{
        //   height: "60%",
        //   width:"100%"
        // }}
        option={{
          
          tooltip: {
            // triggerOn: "none",
            formatter: (params) =>
              `X: ${params.data[0].toFixed(2)}<br>Y: ${params.data[1].toFixed(
                2
              )}`,
          },
          xAxis: {
            type: "value",
            name: "Time (ms)",
            min: minTimeRef.current,
            max: maxTimeRef.current, // Динамическое значение
          },
          yAxis: {
            type: "value",
            name: "Value",
            min: 0,
            max: 127,
          },
          series: [
            {
              type: "line",
              id: "a",
              data: points.map((item, index) => [
                item.time,
                item.value,
                { index },
              ]), // Используем локальное состояние
              symbolSize: 10,
            },
          ],
          dataZoom: [
            {
              type: "slider",
              filterMode: "none",
            },
            {
              type: "inside",
              filterMode: "none",
            },
          ],
        }}
      />
    </div>
  );
};

export default ChangesChart;
