import React, { createContext, useContext, useEffect, useMemo } from "react";

const LoggerContext = createContext();

const LoggerProvider = ({ children }) => {
  const [logs, setLogs] = React.useState([]);

  const addLog = (level, message, metadata = {}) => {
    const newEntry = {
      level,
      message,
      metadata,
      timestamp: new Date(),
    };

    //todo: починить если вообще нужно будет делать список логов setLogs((prev) => [...prev, newEntry]);

    if (process.env.NODE_ENV !== "production") {
      const consoleMethod = console[level] || console.log;
      consoleMethod(`[${level.toUpperCase()}]`, message, metadata);
    }
  };

  const logger = useMemo(() => {
    return ({
      log: (message, metadata = {}) => addLog("log", message, metadata),
      warn: (message, metadata = {}) => addLog("warn", message, metadata),
      error: (message, metadata = {}) =>{return addLog("error", message, metadata)},
      getHistory: () => logs,
      clearHistory: () => setLogs([]),
    });
  }, [logs]);

  return (
    <LoggerContext.Provider value={logger}>{children}</LoggerContext.Provider>
  );
};

export const useLogger = () => {
  const context = useContext(LoggerContext);
  if (!context) {
    throw new Error("useLogger must be used within a LoggerProvider");
  }
  return context;
};

export default LoggerProvider;
