import React from "react";
import useHub from "../../../hooks/useHub";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCircle, faDoorOpen, faLeftLong, faOutdent, faQuidditch, faTooth } from "@fortawesome/free-solid-svg-icons";

const GroupConnectedPanel = ({ styles, groupName, onLeave }) => {
 
  return (
    <div className={styles?.connected_wrapper}>
      <span className={styles?.connection_dot}>
        <FontAwesomeIcon icon={faCircle} />
      </span>
      <span className={styles?.group_name}>{groupName}</span>
      <button className={styles?.leave_btn} onClick={() => onLeave(groupName)}>
        <FontAwesomeIcon icon={faDoorOpen}/>
      </button>
    </div>
  );
};

export default GroupConnectedPanel;
