import React, { useEffect } from "react";
import RemotePlayersList from "../../modules/SharedPlayerModule/SharedPlayersList/RemotePlayersList";
import styles from "./RemoteControllerPage.module.scss";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faDoorOpen,
  faPause,
  faPlay,
  faPlus,
  faStop,
  faX,
} from "@fortawesome/free-solid-svg-icons";
import useHub from "../../hooks/useHub";
import BaseModal from "../../components/Modals/BaseModal";
import NewRemoteGroupForm from "../../modules/SharedPlayerModule/SharedPlayersList/NewRemoteGroupForm";
import { remoteControlState } from "../../modules/SharedPlayerModule/atoms/RemoteControlState";
import { useRecoilState } from "recoil";
import { useLogger } from "../../hooks/useLogger";
import { notification } from "antd";

const RemoteControllerPage = () => {
  const hub = useHub("remote-player");
  const [players, setPlayers] = React.useState([]);
  const logger = useLogger();
  const [notificationApi, contextHolder] = notification.useNotification();
  const handleReceiveGroupParticipants = async (participants) => {
    try {
      setPlayers(participants);
    } catch (error) {
      console.error(error);
    }
  };
  const handleReceiveGroupParticipant = async (participant) => {
    try {
      setPlayers((prev) => [...prev, participant]);
    } catch (error) {
      console.error(error);
    }
  };

  const handleJoinGroup = async (groupName) => {
    try {
      const joinRequest = {
        groupName,
        isMaster: true,
      };

      await hub.invoke("JoinGroup", joinRequest);
    } catch (error) {
      console.error(error);
    }
  };

  const handleReceiveLeaveGroup = async () => {
    try {
      setPlayers([]);
    } catch (error) {
      console.error(error);
    }
  };

  const handleChangeRemoteControl = async (control) => {
    try {
      await hub.invoke("ChangePlayerStateAsync", control);
    } catch (error) {
      console.error(error);
    }
  };

  const handleReceiveMessage = async (message) => {
    try {
      logger.log(message);
      notificationApi.info({
        
        className: "notification",
        message: message,
        type: "info",
      });
    } catch (error) {
      logger.error(error);
    }
  };

  useEffect(() => {
    if (hub.isConnected) {
      hub.on("ReceiveGroupParticipants", handleReceiveGroupParticipants);
      hub.on("ReceiveGroupParticipant", handleReceiveGroupParticipant);
      hub.on("ReceiveGroups", async (groups) => {
        if (groups.length) return;
        setPlayers([]);
      });
      hub.on("ReceiveLeaveGroup", handleReceiveLeaveGroup);
      hub.on("ReceiveMessage", handleReceiveMessage);
    }

    return () => {
      hub.off("ReceiveGroupParticipants");
      hub.off("ReceiveGroupParticipant");
      hub.off("ReceiveGroups");
      hub.off("ReceiveLeaveGroup");
      hub.off("ReceiveMessage");
      hub.invoke("LeaveGroupByConnectionId").finally(() => hub.stop());
    };
  }, [hub.isConnected]);

  useEffect(() => {
    const handleBeforeUnload = () => {
      hub.invoke("LeaveGroupByConnectionId");
    };

    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
    };
  }, [hub]);

  return (
    <div className={styles.wrapper}>
      {contextHolder}
      <aside className={styles.aside}>
        <RemotePlayersList joinGroup={handleJoinGroup} />
        <BaseModal
          styles={styles}
          buttonText={<FontAwesomeIcon icon={faPlus} />}
        >
          <NewRemoteGroupForm
            handleSubmit={async (e) => {
              e.preventDefault();
              const joinRequest = {
                groupName: e.target.groupName.value,
                isMaster: true,
              };
              hub.invoke("CreateGroup", joinRequest);
            }}
            styles={styles}
          />
        </BaseModal>
      </aside>

      <div className={styles.group_content}>
        {players.length ? (
          <div className={styles.participants_list}>
            <div className={styles.navigation}>
              <button
                onClick={async () =>
                  await hub.invoke("LeaveGroupByConnectionId")
                }
                className={styles.leave_btn}
              >
                <FontAwesomeIcon icon={faDoorOpen} />
              </button>
            </div>
            {players.map((player, index) => (
              <div key={index}>
                <div
                  style={{
                    background: player.isMaster ? "rgb(30, 103, 121)" : "none",
                  }}
                  className={styles.participant_item}
                >
                  <p className={styles.participant_name}>
                    {player.name} {player.isMaster && "Мастер"}
                  </p>
                  {!player.isMaster && (
                    <button
                      className={styles?.kikc_btn}
                      onClick={async () =>
                        await hub.invoke(
                          "KickFromGroup",
                          player.connectionId,
                          player.currentGroupName
                        )
                      }
                    >
                      <FontAwesomeIcon icon={faX} />
                    </button>
                  )}
                </div>
              </div>
            ))}
            <div className={styles.control_pannel}>
              <button
                onClick={() =>
                  handleChangeRemoteControl({ RemotePlayerState: 1 })
                }
              >
                <FontAwesomeIcon icon={faPlay} />
              </button>
              <button
                onClick={() =>
                  handleChangeRemoteControl({ RemotePlayerState: 2 })
                }
              >
                <FontAwesomeIcon icon={faPause} />
              </button>
              <button
                onClick={() =>
                  handleChangeRemoteControl({ RemotePlayerState: 3 })
                }
              >
                <FontAwesomeIcon icon={faStop} />
              </button>
            </div>
          </div>
        ) : (
          <p className={styles.no_connections_title}>
            Создайте или подключитесь к группе
          </p>
        )}
      </div>
    </div>
  );
};

export default RemoteControllerPage;
