import { atom, useRecoilState, useResetRecoilState } from "recoil";
import axiosInstance from "../utils/axiosInstance";
import { useNavigate } from "react-router-dom";
import { useEffect } from "react";

const serverErrorState = atom({
  key: "serverErrorState",
  default: [],
});

const useServer = () => {
  const navigate = useNavigate();
  const [serverErrors, setServerErrors] = useRecoilState(serverErrorState);

  useEffect(() => {
    const interceptor = axiosInstance.interceptors.response.use(
      (response) => response,
      (error) => {
        if (!error.response) {
          return Promise.reject(error);
        }

        const errorData = {
          exceptionMessage:
            error.response?.data?.exceptionMessage || "Произошла ошибка",
          exceptionText:
            error.response?.data?.exceptionText || "Неизвестная ошибка",
          statusCode: error.response?.status,
          timestamp: Date.now(),
        };

        setServerErrors((prev) => {
          const lastError = prev[prev.length - 1];
          const isSameError =
            lastError &&
            lastError.statusCode === errorData.statusCode &&
            lastError.exceptionMessage === errorData.exceptionMessage &&
            Date.now() - lastError.timestamp < 1000; 

          return isSameError ? prev : [...prev, errorData];
        });

        if (error.response.status === 401) {
          navigate("/");
        }

        return Promise.reject(error);
      }
    );

    return () => {
      axiosInstance.interceptors.response.eject(interceptor);
    };
  }, [navigate, setServerErrors]);

  const get = async (url, config = {}) => {
    const response = await axiosInstance.get(url, config);
    return response.data;
  };

  const post = async (url, data, config = {}) => {
    const response = await axiosInstance.post(url, data, config);
    return response.data;
  };

  const put = async (url, data, config = {}) => {
    const response = await axiosInstance.put(url, data, config);
    return response.data;
  };

  const del = async (url, config = {}) => {
    const response = await axiosInstance.delete(url, config);
    return response.data;
  };

  const getToken = () => {
    return localStorage.getItem("Authorization")?.split(" ")[1];
  };

  return {
    get,
    post,
    put,
    del,
    getToken,
    serverErrors,
  };
};

export default useServer;
