import React from "react";
import { Link, Outlet, useLocation } from "react-router-dom";
import style from "./styles/AuthLayout.module.scss";

const AuthLayout = () => {
  const location = useLocation();

  return (
    <div className={style.wrapper}>
      <div className={style.aside}>
        <div className={style.navigation}>
          <span className={style.logo}>Autolizer</span>
          {location.pathname === "/auth/registration" ? (
            <div className={style.sign_in}>Уже есть аккаунт? <br/> <Link to="/auth/authentication">Вход</Link></div>
          ) : (
             <Link to="/auth/registration">Регистрация</Link>
          )}
        </div>
      </div>
      <div className={style.form}>
        <Outlet />
      </div>
    </div>
  );
};

export default AuthLayout;
