import { useEffect, useState } from "react";
import { HubConnectionBuilder } from "@microsoft/signalr";
import useServer from "./useServer";
import { useLogger } from "./useLogger";

const useHub = (hub) => {
  const { getToken } = useServer();
  const logger = useLogger();
  const [connection, setConnection] = useState(null);
  const [isConnected, setIsConnected] = useState(false);

  const joinHub = async () => {
    const token = getToken();
    if (!token) {
      logger.warn("Токен не найден. Подключение к хабу невозможно.");
      return;
    }

    const connection = new HubConnectionBuilder()
      .withUrl(`https://localhost:7115/${hub}`, {
        accessTokenFactory: () => token,
      })
      .withAutomaticReconnect()
      .build();

    try {
      await connection.start();
      setConnection(connection);
      setIsConnected(true);
    } catch (error) {
      logger.error(`Ошибка подключения к хабу: ${error}`);
      setIsConnected(false);
    }
  };

  useEffect(() => {
    if (!connection) {
      joinHub();
    }

    return () => {
      if (connection) {
        connection.stop();
        logger.log(`Отключились от хаба: ${hub}`);
        setIsConnected(false);
      }
    };
  }, [hub]);

  const invoke = async (hubFunction, ...args) => {
    if (!connection || !isConnected) {
      logger.warn("Хаб не подключен");
      return;
    }

    try {
      await connection.invoke(hubFunction, ...args);
    } catch (error) {
      logger.error(`Ошибка при вызове метода хаба: ${error}`);
    }
  };

  const on = (eventName, callback) => {
    if (!connection || !isConnected) {
      logger.warn("Хаб не подключен");
      return;
    }

    connection.on(eventName, callback);
  };

  const off = (eventName, callback) => {
    if (!connection || !isConnected) {
      logger.warn("Хаб не подключен");
      return;
    }
    connection.off(eventName, callback);
  };

  const stop = async () => {
    if (connection) {
      connection.stop();
      logger.log(`Отключились от хаба: ${hub}`);
      setIsConnected(false);
    }
  };

  return { invoke, on, off, isConnected, stop };
};

export default useHub;
