import React from 'react'

const NewRemoteGroupForm = ({styles, handleSubmit}) => {
  return (
    <form onSubmit={handleSubmit} className={styles?.new_group_form}>
      <label className={styles?.new_group_label} >Название группы:</label>
      <input className={styles?.new_group_input} type="text" name="groupName" />
      <button className={styles?.new_group_btn} type="submit">Создать</button>
    </form>
  )
}

export default NewRemoteGroupForm