import React, { useState } from "react";
import { useForm } from "react-hook-form";
import { Upload, Button } from "antd";
import { UploadOutlined } from "@ant-design/icons";
import useServer from "../../../hooks/useServer";
import { useNavigate } from "react-router-dom";
import style from "./NewPresetForm.module.scss";
import { useLogger } from "../../../hooks/useLogger";

const NewPresetForm = () => {
  const navigate = useNavigate();
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm();
  const { post } = useServer();
  const logger = useLogger();
  const [file, setFile] = useState(null);

  // Функция обработки загрузки файла
  const handleFileChange = ({ file }) => {
    setFile(file);
  };

  // Функция обработки формы
  const onSubmit = async (data) => {
    logger.log("Submitted Data:", data);

    // Создаем FormData для отправки данных
    const formData = new FormData();
    formData.append("name", data.name);
    formData.append("description", data.description);
    if (file) {
      formData.append("imageFile", file);
    }

    try {
      const res = await post("preset/create-preset", formData);
      navigate(`/work/preset/${res.id}`);
    } catch (error) {
      logger.error(error);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className={style.form}>
      <div className={style.form_item}>
        <input
          className={style.input}
          {...register("name", { required: true })}
          placeholder="название"
        />
        {errors.name && <p style={{ color: "red" }}>Введите название</p>}
      </div>

      <div className={style.form_item}>
        <Upload
          className={style.upload}
          beforeUpload={() => false} // Отключаем автоматическую загрузку
          onChange={handleFileChange}
          maxCount={1}
          accept="image/*"
          listType="picture"
          // showUploadList={false} // Скрываем список загруженных файлов
        >
          <Button className={style.upload_btn} icon={<UploadOutlined />}>Загрузить изображение</Button>
        </Upload>
      </div>

      <div className={style.form_item}>
        <button type="submit" className={style.button}>
          Создать Пресет
        </button>
      </div>
    </form>
  );
};

export default NewPresetForm;
