import React, { useState } from "react";
import { useParams } from "react-router-dom";
import { useRecoilState } from "recoil";
import { presetPlayerState } from "../atoms/presetDataState";
import useServer from "../../../hooks/useServer";
import { FileAddOutlined } from "@ant-design/icons";
import { notification, Upload, Button, Progress } from "antd";
import { audioUploadState } from "../atoms/audioUploadState";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faDownload,
  faFile,
  faFileAudio,
  faNotesMedical,
  faNoteSticky,
} from "@fortawesome/free-solid-svg-icons";
import { useLogger } from "../../../hooks/useLogger";

const AudioFileHandler = ({ styles }) => {
  const [preset, setPreset] = useRecoilState(presetPlayerState);
  const { put } = useServer();
  const { id } = useParams();
  const logger = useLogger();
  const [uploadProgress, setUploadProgress] = useState(0); 
  const [isUploading, setIsUploading] = useRecoilState(audioUploadState);

  const [api, contextHolder] = notification.useNotification();

  const handleFileChange = async ({ file, onProgress }) => {
    if (file.status === "uploading") {
      setIsUploading(true);
      return;
    }
    if (file.status !== "done") return;

    const formData = new FormData();
    formData.append("formFile", file.originFileObj);

    try {
      const res = await put(`preset/add-audio/${id}`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      setPreset((prev) => ({
        ...prev,
        audioUrl: res,
        audioName: file.name,
      }));

      api.success({
        message: "Аудио-файл добавлен",
        placement: "top",
        className: "notification"
      });
    } catch (error) {
      logger.error("Ошибка при загрузке файла:", error);
      api.error({
        message: "Ошибка при загрузке файла",
        placement: "topRight",
      });
    } finally {
      setIsUploading(false);
      setUploadProgress(0);
    }
  };

  return (
    <div className={styles.file_container}>
      {contextHolder}

      <Upload
        customRequest={({ file, onSuccess }) => {
          setTimeout(() => onSuccess("ok"), 0);
        }}
        onChange={handleFileChange}
        className={styles.upload}
        showUploadList={false}
      >
        <button disabled={isUploading}>
          {isUploading ? "Загрузка..." : <FontAwesomeIcon icon={faDownload} />}
        </button>
      </Upload>
    </div>
  );
};

export default AudioFileHandler;
