import React from "react";
import { useForm } from "react-hook-form";
import styles from "./LoginForm.module.scss"; // Подключение модуля стилей
import { useAuth } from "../../../contexts/AuthProvider"; // Импортируйте ваш AuthProvider

const LoginForm = () => {
  const { login } = useAuth();
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm();

  const onSubmit = (data) => {
    login(data.login, data.password);
  };

  return (
    <div className={styles.form_wrap}>
      <form onSubmit={handleSubmit(onSubmit)} className={styles.loginForm}>
        <div className={styles.formItem}>
          {/* <label className={styles.customLabel}>Логин или почта</label> */}
          <input
            {...register("login", {
              required: "Пожалуйста, введите ваш логин или почту!",
            })}
            placeholder="Введите логин или почту"
          />
          {errors.login && (
            <p className={styles.errorText}>{errors.login.message}</p>
          )}
        </div>

        <div className={styles.formItem}>
          {/* <label className={styles.customLabel}>Пароль</label> */}
          <input
            type="password"
            {...register("password", {
              required: "Пожалуйста, введите ваш пароль!",
            })}
            placeholder="Введите пароль"
          />
          {errors.password && (
            <p className={styles.errorText}>{errors.password.message}</p>
          )}
        </div>

        <div className={styles.formItem}>
          <button type="submit" className={styles.submitButton}>
            Войти
          </button>
        </div>
      </form>
    </div>
  );
};

export default LoginForm;
