import React, { forwardRef, useEffect, useRef, useState } from "react";
import { useRecoilState, useRecoilValue } from "recoil";
import { presetDataState, presetPlayerState } from "../atoms/presetDataState";
import style from "../ControlElementsBlock.module.scss";
import { Button } from "antd";
import * as Tone from "tone";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faPlay,
  faPause,
  faStop,
  faStopCircle,
  faCircleStop,
  faPlayCircle,
  faPauseCircle,
} from "@fortawesome/free-solid-svg-icons"; // Импортируйте нужные иконки
import { PlaySquareFilled, XFilled } from "@ant-design/icons";
import usePlayer from "../../../hooks/usePlayer";

const NewRecordControl = forwardRef((_, ref) => {
  const data = useRecoilValue(presetDataState);
  const [prepaired, setPrepaired] = useState([]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [presetPlayer] = useRecoilState(presetPlayerState);
  const midiRef = useRef(null);
  const player = usePlayer(prepaired, handlePlay, {
    url: presetPlayer?.audioUrl || "",
    from: 0,
    to: 0,
  });

  useEffect(() => {
    if (navigator.requestMIDIAccess) {
      navigator.requestMIDIAccess().then((access) => {
        const outputs = access.outputs.values();
        const output = outputs.next().value;
        midiRef.current = output;
      });
    }
  });

  useEffect(() => {
    const changesWithMetadata = data
      .flatMap((d) =>
        d.times.map((time) => ({
          ccType: d.ccType,
          guid: d.guid,
          name: d.name,
          changes: time.changes,
        }))
      )
      .flatMap((item) =>
        item.changes.map((change) => ({
          ...change,
          ccType: item.ccType,
          guid: item.guid,
          name: item.name,
        }))
      );

    setPrepaired(changesWithMetadata);
  }, [data]);

  function handlePlay(item) {
    if (midiRef.current) {
      midiRef.current.send([0xb0, item?.ccType, item.value]);
    }
  }

  React.useImperativeHandle(ref, () => ({
    play: player.play,
    pause: player.pause,
    stop: player.stop,
  }));

  return (
    <div className={style.control_buttons}>
      <button
        className={style.play_btn}
        disabled={player.isPlaying}
        onClick={player.play}
      >
        <FontAwesomeIcon icon={faPlayCircle} />
      </button>
      <button
        className={style.pause_btn}
        onClick={player.pause}
        disabled={!player.isPlaying}
      >
        <FontAwesomeIcon icon={faPauseCircle} />
      </button>
      <button
        disabled={!player.isPlaying}
        className={style.stop_btn}
        onClick={player.stop}
      >
        <FontAwesomeIcon icon={faCircleStop} />
      </button>
    </div>
  );
});

export default NewRecordControl;
