import React, { useEffect, useState } from "react";
import useServer from "../../../hooks/useServer";
import { useParams } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faHeart,
  faLock,
  faPerson,
  faUnlock,
  faUserGroup,
} from "@fortawesome/free-solid-svg-icons";
import ConditionalRenderer from "../../../components/ConditionalRendering/ConditionalRenderer";
import { notification } from "antd";
import { useLogger } from "../../../hooks/useLogger";

const SharedInfo = ({ preview = true, styles }) => {
  const { id } = useParams();
  const { get, put } = useServer();
  const logger = useLogger();
  const [api, contextHolder] = notification.useNotification({
    maxCount:1,
    stack:false
  });
  const [data, setData] = useState({});
  const [isShared, setIsShared] = useState(false)

  useEffect(() => {
    setIsShared(!data.isStashed);
  }, [data])

  const fetch = async () => {
    try {
      const response = await get(`preset/get-shared-info/${id}`);
      setData(response);
      logger.log(response);
    } catch (error) {
      logger.log(error);
    }
  };
  const handleLike = async () => {
    try {
      const response = await put(
        `preset/toggle-like/${id}/${!data.isLikedByMe}`
      );
      setData((perv) => ({
        ...perv,
        isLikedByMe: !perv.isLikedByMe,
        likesCount: perv.likesCount + (perv.isLikedByMe ? -1 : 1),
      }));
    } catch (error) {
      logger.log(error);
    }
  };

  const handleToggleShared = async () => {
    try {
      const response = data?.isStashed
        ? await put(`preset/set-as-shared/${id}`)
        : await put(`preset/set-as-stashed/${id}`);
      
      setData((prev) => ({
        ...prev,
        isStashed: !prev.isStashed,
      }));
      
      const newIsShared = !data.isStashed;
      setIsShared(newIsShared);
  
      api.info({
        placement: "top",
        message: !newIsShared 
          ? "Публичен" 
          : "Спрятан",
        className:"notification" ,
      });
      
    } catch (error) {
      api.error({
        placement: "top",
        message: "не получилось спрятать пресет",
        className: "notification-error"
      });
      logger.log(error);
    }
  };

  useEffect(() => {
    fetch();
  }, []);

  return (
    <div className={styles.shared_container}>
      <ConditionalRenderer condition={() => preview}>
        <span className={styles.shared_info}>
          {data?.likesCount ? data?.likesCount : 0}{" "}
          {data.isMyPrest ? (
            <FontAwesomeIcon className={styles.likes} icon={faHeart} />
          ) : (
            <button className={styles.like_btn} onClick={handleLike}>
              <FontAwesomeIcon
                style={data.isLikedByMe ? { color: "red" } : {}}
                icon={faHeart}
              />
            </button>
          )}
        </span>
      </ConditionalRenderer>
      <ConditionalRenderer condition={() => !preview}>
        {contextHolder}
        <button onClick={handleToggleShared} className={styles.toggle_shared_btn}>
          <FontAwesomeIcon icon={isShared ? faUnlock : faLock} />
        </button>
      </ConditionalRenderer>
    </div>
  );
};

export default SharedInfo;
