import React, { useEffect } from "react";
import RemotePlayersList from "./RemotePlayersList";
import { useParams } from "react-router-dom";
import BaseModal from "../../../components/Modals/BaseModal";
import GroupConnectedPanel from "./GroupConnectedPanel";
import styles from "./RemotePlayersList.module.scss";
import { useHubContext } from "../../../contexts/HubContext";
import { useLogger } from "../../../hooks/useLogger";
import { message, notification } from "antd";

const RemotePreset = () => {
  const { hub } = useHubContext();
  const { id } = useParams();
  const logger = useLogger();
  const [connectedGroup, setConnectedGroup] = React.useState(null);
  const [notificationApi, contextHolder] = notification.useNotification();

  const joinGroup = async (groupName) => {
    try {
      const joinRequest = {
        groupName,
        presetId: Number(id),
        isMaster: false,
      };
      await hub.invoke("JoinGroup", joinRequest);
    } catch (error) {
      logger.error(error);
    }
  };

  const receiveGroup = async (group) => {
    try {
      setConnectedGroup(group);
    } catch (error) {
      logger.error(error);
    }
  };

  const receiveLeaveGroup = async () => {
    try {
      setConnectedGroup(null);
    } catch (error) {
      logger.error(error);
    }
  };

  const handleDisconnect = async (groupName) => {
    try {
      await hub.invoke("LeaveGroup", groupName);
      setConnectedGroup(null);
    } catch (error) {
      logger.error(error);
    }
  };

  const receiveMessage = async (message) => {
    try {
      logger.log(message);
      notificationApi.warning({
        placement:"top",
        message: message,
        className: "notification"
      });
    } catch (error) {
      logger.error(error);
    }
  };

  useEffect(() => {
    if (hub.isConnected) {
      hub.on("ReceiveGroup", receiveGroup);
      hub.on("ReceiveLeaveGroup", receiveLeaveGroup);
      hub.on("ReceiveMessage", receiveMessage);
    }
  }, [hub.isConnected]);

  useEffect(() => {
    const handleBeforeUnload = () => {
      hub.invoke("LeaveGroupByConnectionId");
    };

    window.addEventListener("beforeunload", handleBeforeUnload);

    return () => {
      window.removeEventListener("beforeunload", handleBeforeUnload);
      hub.stop();
    };
  }, [hub]);

  return (
    <div className={styles.remote_preset_wrapper}>
      {contextHolder}
      {connectedGroup ? (
        <GroupConnectedPanel
          styles={styles}
          onLeave={handleDisconnect}
          groupName={connectedGroup.name}
        />
      ) : (
        <BaseModal styles={styles} buttonText={"группы"}>
          <RemotePlayersList joinGroup={joinGroup} />
        </BaseModal>
      )}
    </div>
  );
};

export default RemotePreset;
