import React, { useEffect, useRef } from "react";
import usePlayer from "../../hooks/usePlayer";
import { useRecoilState, useRecoilValue } from "recoil";
import {
  controlElementChangesHistoryState,
  controlElementState,
  presetState,
} from "../../pages/ControlElementHandlerPage/atoms/RecordsStates";
import { ftom } from "tone";
import {
  MinusCircleOutlined,
  PauseCircleOutlined,
  PlayCircleOutlined,
} from "@ant-design/icons";
import style from "./PlayerModule.module.scss";
import { Button } from "antd";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPause, faPlay, faStop } from "@fortawesome/free-solid-svg-icons";
import { WaveFormState } from "../../pages/ControlElementHandlerPage/atoms/WaveFormState";

const NewPlayerModule = ({ audioUrl = "", playFrom = 0, playFor = 0 }) => {
  const changes = useRecoilValue(controlElementChangesHistoryState);
  const controlElementData = useRecoilValue(controlElementState);
  const preset = useRecoilValue(presetState);
  const midiRef = useRef(null);

  const lastChange = changes.length > 0 ? changes[changes.length - 1] : [];

  const [from, setFrom] = React.useState(0);

  const [to, setTo] = React.useState(0);

  const player = usePlayer(changes[changes.length - 1], handleChanges, {
    url: preset?.audioUrl || "",
    from: from,
    to: to,
  });
  useEffect(() => {
    if (navigator.requestMIDIAccess) {
      navigator.requestMIDIAccess().then((access) => {
        const outputs = access.outputs.values();
        const output = outputs.next().value;
        midiRef.current = output;
      });
    }
  });

  useEffect(() => {
    setFrom(
      lastChange.length > 0
        ? Math.min(...lastChange.map((item) => item.time))
        : 0
    );
    setTo(
      lastChange.length > 0
        ? Math.max(...lastChange.map((item) => item.time))
        : 0
    );
  }, [changes]);
  function handleChanges(item) {
    if (midiRef.current) {
      midiRef.current.send([0xb0, controlElementData?.ccType, item.value]);
    }
  }

  return (
    <div className={style.player_wrapper}>
      <button
        style={{
          background: "none",
          border: "none",
        }}
        className={style.play_button}
        disabled={player.isPlaying}
        onClick={player.play}
      >
        <FontAwesomeIcon icon={faPlay} />
      </button>
      <button
        style={{
          background: "none",
          border: "none",
        }}
        className={style.pause_button}
        onClick={player.pause}
        disabled={!player.isPlaying}
      >
        <FontAwesomeIcon icon={faPause} />
      </button>
      <button
        style={{
          background: "none",
          border: "none",
        }}
        className={style.stop_button}
        onClick={player.stop}
      >
        <FontAwesomeIcon icon={faStop} />
      </button>
    </div>
  );
};

export default NewPlayerModule;
