import { BrowserRouter, Route, Router, Routes } from "react-router-dom";
import "./App.css";
import { PressetPage } from "./pages";
import MainLayout from "./pages/Layouts/MainLayout";
import HomePage from "./pages/HomePage/HomePage";
import AuthLayout from "./pages/Layouts/AuthLayout";
import RegistrationForm from "./components/Forms/RegistrationForm/RegistrationForm";
import { AuthProvider, useAuth } from "./contexts/AuthProvider";
import LoginForm from "./components/Forms/LoginForm/LoginForm";
import WorkLayout from "./pages/Layouts/WorkLayout";
import PresetListPage from "./pages/PresetListPage/PresetListPage";
import NewPresetForm from "./components/Forms/NewPresetForm/NewPresetForm";
import ControlElementHandler from "./pages/ControlElementHandlerPage/ControlElementHandler";
import { useEffect } from "react";
import { notification } from "antd";
import AboutVirtualMidiPortPage from "./pages/AboutVirtualMidiPortPage/AboutVirtualMidiPortPage";
import SharedPresetsListPage from "./pages/SharedPresetsListPage/SharedPresetsListPage";
import CrumbsProvider from "./utils/CrumbsProvider";
import { HomeFilled } from "@ant-design/icons";
import { faHome } from "@fortawesome/free-solid-svg-icons";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import RemoteControllerPage from "./pages/RemoteControllerPage/RemoteControllerPage";
import useServer from "./hooks/useServer";
import ServerErrorsLogHandler from "./components/ServerErrorsLogHandler/ServerErrorsLogHandler";

function App() {
  

  return (
    <>
    <ServerErrorsLogHandler/>
      <CrumbsProvider>
        <Routes>
          <Route
            crumb={<FontAwesomeIcon icon={faHome} />}
            path="/"
            element={<MainLayout />}
          >
            <Route index element={<HomePage />} />
            <Route
              crumb={"про midi"}
              path="midi-ports-list"
              element={<AboutVirtualMidiPortPage />}
            />
            <Route path="auth" element={<AuthLayout />}>
              <Route
                crumb={"вход"}
                index
                path="authentication"
                element={<LoginForm />}
              />
              <Route
                crumb={"регистрация"}
                path="registration"
                element={<RegistrationForm />}
              />
            </Route>
            <Route crumb={"рабочая"} path="work" element={<WorkLayout />}>
              <Route index element={<PresetListPage />} />
              <Route path="preset/:id">
                <Route
                  crumb={"пресет"}
                  index
                  element={<PressetPage preview={false} />}
                />
                <Route
                  crumb={"элемент управления"}
                  path="control-element/:timeIndex/:controlElementGuid"
                  element={<ControlElementHandler />}
                />
              </Route>
              <Route path="shared-presets">
                <Route
                  crumb={"общие"}
                  index
                  element={<SharedPresetsListPage />}
                />
                <Route
                  crumb={"preview"}
                  path="preset-preview/:id"
                  element={<PressetPage preview={true} />}
                />
              </Route>
              <Route
                path="remote-controller"
                element={<RemoteControllerPage />}
              />
              <Route path="new-preset" element={<NewPresetForm />} />
            </Route>
          </Route>
        </Routes>
      </CrumbsProvider>
    </>
  );
}

export default App;
