import React, { useEffect } from "react";
import style from "./SharedPresetsListPage.module.scss";
import SharedPresetsListModule from "../../modules/SharedPresetsListModule/SharedPresetsListModule";
import PresetsListFetchModule from "../../modules/PresetsFilterModule/PresetsListFetchModule";
import { useRecoilState } from "recoil";
import {
  isLoadingState,
  pagesState,
  sharedPresetsState,
} from "./atoms/sharedPresesAtoms";
import PaginationModule from "../../modules/PaginationModule/PaginationModule";
import useHeader from "../../hooks/useHeader";

const SharedPresetsListPage = () => {
  const [sharedPresets, setSharedPresets] = useRecoilState(sharedPresetsState);
  const [pages, setPages] = useRecoilState(pagesState);
  const [loading, setLoading] = useRecoilState(isLoadingState);

  return (
    <div className={style.wrapper}>
      <div className={style.list_wrapper}>
        <SharedPresetsListModule presets={sharedPresets} loading={loading} />
      </div>

      <div className={style.pagination}>
        <PresetsListFetchModule
          pageCount={pages.presetsOnPage}
          pageNumber={pages.currentPage}
          setPresets={setSharedPresets}
          setLoading={setLoading}
          setPages={setPages}
        />
        <PaginationModule
          setPages={setPages}
          currentPage={pages.currentPage}
          pageSize={pages.presetsOnPage}
          totalCount={sharedPresets.length}
        />
      </div>
    </div>
  );
};

export default SharedPresetsListPage;
