import React, { useEffect, useState } from "react";
import "antd/dist/reset.css";
import style from "./HomePage.module.scss";
import { ButtonBase } from "../../components";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../../contexts/AuthProvider";
import { DownloadOutlined, FileOutlined } from "@ant-design/icons";
import { QRCode } from "antd";
import TelegramAuthButton from "../../modules/TelegramAuthButton/TelegramAuthButton";

const HomePage = () => {
  const navigate = useNavigate();
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const { getJwtLifeTime } = useAuth();

  useEffect(() => {
    const jwtLifeTime = getJwtLifeTime();
    const expiryTime = jwtLifeTime * 1000;

    if (jwtLifeTime && jwtLifeTime > 0) {
      setIsAuthenticated(true);
    }

    const timeoutLogout = setTimeout(() => {
      setIsAuthenticated(false);
    }, expiryTime);

    return () => {
      clearTimeout(timeoutLogout);
    };
  }, [getJwtLifeTime, navigate]);

  return (
    <main className={style.wrapper}>
      <header>
        <nav>
          <span className={style.brand}>Autolizer</span>
          <ul className={style.nav_list}>
            <li className={style.nav_item}>
              <a href="#for_what">для чего</a>
            </li>
            <li className={style.nav_item}>
              <a href="#how_it_works">как это работает</a>
            </li>
          </ul>
          <div className={style.reg_auth}>
            {isAuthenticated ? (
              <ButtonBase
                action={() => navigate("/work")}
                className={`${style.sign_btn}`}
                text="к пресетам"
              />
            ) : (
              <TelegramAuthButton />
            )}
          </div>
        </nav>

        <div className={style.slogan_block}>
          <p>
            <span className={style.highlight}>Autolizer</span> — Контроль
            <br></br> над музыкой
          </p>
        </div>
      </header>

      <section id="for_what" className={style.for_what}>
        <div className={style.for_what_content}>
          <h1>Для чего этот проект</h1>
          <p className={style.for_what_info}>
            <span>Autolizer</span> - это проект, который позволяет музыкантам
            автоматизировать управление звуковыми эффектами, такими как
            громкость, модуляция и реверберация. Больше не нужно отвлекаться на
            педали эффектов или MIDI-контроллеры во время игры. Настройте
            параметры заранее и запускайте их автоматически в нужные моменты.
          </p>
        </div>
      </section>

      <section id="how_it_works" className={style.how_it_works}>
        <div className={style.how_it_works_content}>
          <h1>Как это работает</h1>
          <div className={style.instruction}>
            <div id="step-1" className={style.instruction_item}>
              <span>
                <span className={style.step_number}>1</span> установка
                виртуального midi-порта
              </span>
              <p>
                Сначала установите виртуальный MIDI-порт, который позволит
                приложению взаимодействовать с целевыми программами
              </p>
              <Link className={style.midi_ports_link} to="/midi-ports-list">
                Подробнее
              </Link>
            </div>
            <div id="step-2" className={style.instruction_item}>
              <span>
                <span className={style.step_number}>2</span> создание пресета{" "}
              </span>
              <p>
                Создайте пресет и добавте элементы управления, которые будут
                отдельными элементами в целевой программе
              </p>
            </div>
            <div id="step-3" className={style.instruction_item}>
              <span>
                {" "}
                <span className={style.step_number}>3</span> настройка элементов
                управления
              </span>
              <p>У элемента управления создайте записи</p>
            </div>
            <div id="step-4" className={style.instruction_item}>
              <span>
                {" "}
                <span className={style.step_number}>4</span> настройка трека
                автоматизации
              </span>
              <p>
                Для каждой записи создайте трек автоматизации и нарисуйте его с
                помощю графического редактора
              </p>
            </div>
          </div>

          <div className={style.more_info}>
            <div className={style.links_side}>
              <QRCode
                color="#6fffe9"
                className={style.qr_code}
                errorLevel="L"
                size={300}
                value="https://goo.su/nZ30g2Q"
              ></QRCode>
              <a
                href="https://goo.su/nZ30g2Q"
                className={style.iinstructuion_link}
                download="Autolizer-инструкция пользователя.docx"
              >
                <DownloadOutlined /> инструкция пользователя
              </a>
            </div>
            <div className={style.text_side}>
              <span>Скачайте подробную инструкцию</span>
            </div>
          </div>
        </div>
      </section>

      <section className={style.footer}>
        <div className={style.more_info}>
          <h1>Смачная шапка сайта</h1>
        </div>
      </section>
    </main>
  );
};

export default HomePage;
