import React, { useEffect } from "react";
import useServer from "../../hooks/useServer";
import { notification } from "antd";

const ServerErrorsLogHandler = () => {
  const server = useServer();
  const [notificationApi, contextHolder] = notification.useNotification();

  useEffect(() => {
    if (server.serverErrors.length > 0) {
      const lastError = server.serverErrors[server.serverErrors.length - 1];
      notificationApi.error({
        message: `${lastError?.statusCode} – ${lastError?.exceptionMessage}`,
        description: lastError?.exceptionMessage,
      });
    }
  }, [server.serverErrors]);
  return <>{contextHolder}</>;
};

export default ServerErrorsLogHandler;
