import { atom, useResetRecoilState } from "recoil";

export const sharedPresetsState = atom({
  key: "sharedPresetsState",
  default: []
});

export const isLoadingState = atom({
  key: "isLoadingState",
  default: false,
});

export const pagesState = atom({
  key: "pagesState",
  default: {
    presetsOnPage: 10,
    currentPage: 1,
  },
});

export const useResetAllPresetsState = () => {
  const resetSharedPresets = useResetRecoilState(sharedPresetsState);
  const resetIsLoading = useResetRecoilState(isLoadingState);
  const resetPages = useResetRecoilState(pagesState);

  return () => {
    resetSharedPresets();
    resetIsLoading();
    resetPages();
  };
};
