import React, { useEffect } from "react";
import useServer from "../../hooks/useServer";
import usePresetsListFetch from "../../hooks/usePresetsListFetch";
import { FilterOutlined } from "@ant-design/icons";
import { Dropdown, Menu } from "antd";
import style from "./PresetsListFetchModule.module.scss";

const PresetsListFetchModule = ({
  pageNumber,
  setLoading,
  pageCount,
  setPresets = (d) => {},
}) => {
  const { fetchPresets, setEndPoint, endPoint, EndPoints } =
    usePresetsListFetch();

  useEffect(() => {
    const loadPresets = async () => {
      try {
        setLoading(true)
        const data = await fetchPresets(pageCount, pageNumber);

        setPresets(data);
      } catch (error) {
        console.error(error);
      } finally {
        setLoading(false);
      }
    };

    loadPresets();
  }, [pageNumber, pageCount, endPoint]);

  const items = [
    { key: "get-shared", label: "Общие" },
    { key: "get-liked", label: "Понравившиеся" },
    { key: "get-my", label: "Мои" },
  ];

  return (
    <Dropdown
    overlayClassName={style.drop_list}
      menu={{ items, onClick: (e) => setEndPoint(e.key) }}
      trigger={["click"]}
    >
      <FilterOutlined className={style.filter_icon} style={{ fontSize: 24, cursor: "pointer" }} />
    </Dropdown>
  );
};

export default PresetsListFetchModule;
