import React, { useEffect, useState } from "react";
import useServer from "../../../hooks/useServer";
import { useLocation, useParams } from "react-router-dom";
import RecordControl from "./RecordControl";
import styles from "../ControlElementsBlock.module.scss";
import AudioFileHandler from "./AudioFileHandler";
import { presetPlayerState } from "../atoms/presetDataState";
import { useRecoilState, useResetRecoilState } from "recoil";
import { notification } from "antd";
import { useBreadCrumbs } from "../../../utils/CrumbsProvider";
import ConditionalRenderer from "../../../components/ConditionalRendering/ConditionalRenderer";
import SharedInfo from "./SharedInfo";
import NewRecordControl from "./NewRecordControl";
import RemotePreset from "../../SharedPlayerModule/SharedPlayersList/RemotePreset";
import WithRemoteRecordControl from "../../SharedPlayerModule/Hocs/WithRemoteRecordControl";
import { useLogger } from "../../../hooks/useLogger";

const PresetHeader = ({ preview }) => {
  const { id } = useParams();
  const { get } = useServer();
  const logger = useLogger();
  const { setBreadCrumbs, breadCrumbs } = useBreadCrumbs();
  const location = useLocation();

  const [preset, setPreset] = useRecoilState(presetPlayerState);
  const resetPreset = useResetRecoilState(presetPlayerState);

  const [api, contextHolder] = notification.useNotification();
  const getPresetInfo = async () => {
    try {
      const res = await get(`Preset/get-preset/${id}`);

      setPreset(res);
    } catch (error) {
      logger.log(error);
    }
  };

  useEffect(() => {
    ///TODO: вынести в хук этот метод
    const updatedCrumbs = breadCrumbs.map((crumbObj) => {
      if (crumbObj.path.includes(":")) {
        const pattern = "^" + crumbObj.path.replace(/:[^/]+/g, "([^/]+)") + "$";
        const regex = new RegExp(pattern);
        const match = location.pathname.match(regex);

        if (match) {
          const id = match[1];

          return { ...crumbObj, crumb: preset.name };
        }
      }
      return crumbObj;
    });

    setBreadCrumbs(updatedCrumbs);
  }, [preset]);

  useEffect(() => {
    getPresetInfo().then((res) => {});

    return () => {
      resetPreset();
    };
  }, []);

  const EnhancedRecordControl = WithRemoteRecordControl(NewRecordControl);

  return preset ? (
    <div className={styles.preset_header}>
      <div className={styles.info}>
        <div className={styles.controls}>
          <ConditionalRenderer condition={() => !preview}>
            <AudioFileHandler styles={styles} />
          </ConditionalRenderer>
          {/* <RecordControl/> */}
          {/* <NewRecordControl /> */}
          <EnhancedRecordControl />
          {preset.audioName && (
            <span className={styles.file_name}>{preset.audioName}</span>
          )}
        </div>
        <div className={styles.instruments_wrapper}>
          <SharedInfo preview={preview} styles={styles} />
          <RemotePreset />
        </div>
      </div>
    </div>
  ) : (
    <span>Загружаем...</span>
  );
};

export default PresetHeader;
