import React from "react";
import { atom, useRecoilState, useResetRecoilState } from "recoil";
import { useLogger } from "./useLogger";

const headerState = atom({
  key: "headerState",
  default: (
    <h1
      style={{
        color: "#6fffe9",
        fontSize: "40pt",
        fontWeight: "100",
      }}
    >
      Autolizer
    </h1>
  ),
});

const useHeader = (initialHeader) => {
  const logger = useLogger();
  const [header, setHeader] = useRecoilState(headerState);
  const resetHeader = useResetRecoilState(headerState);
  const getHeader = () => header;

  const setNewHeader = (newHeader) => {
    if (React.isValidElement(newHeader)) {
      setHeader(newHeader);
    } else {
      logger.error("Invalid JSX component");
    }
  };

  React.useEffect(() => {
    if (initialHeader && React.isValidElement(initialHeader)) {
      setHeader(initialHeader);
    }

    return () => {
      resetHeader();
    };
  }, []);

  return {
    getHeader,
    setNewHeader,
  };
};

export default useHeader;
