import React, { useEffect } from "react";
import useHub from "../../../hooks/useHub";
import { Button, Modal } from "antd";
import RemotePlayerListItem from "./RemotePlayerListItem";
import styles from "./RemotePlayersList.module.scss";
import { useParams } from "react-router-dom";

const RemotePlayersList = ({joinGroup = async (groupName) => {}}) => {
  const hub = useHub("remote-player");
  const [players, setPlayers] = React.useState([]);
  const [loading, setLoading] = React.useState(false);

  const handleReceiveGroups = (msg) => {
    try {
      setPlayers(msg);
    } catch (error) {
      console.error(error);
    }
  };

  const fetchGroups = async () => {
    try {
      setLoading(true);
      await hub.invoke("GetGroups");
    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (hub.isConnected) {
      hub.on("ReceiveGroups", handleReceiveGroups);
    }
  }, [hub.isConnected]);

  useEffect(() => {
    if (hub.isConnected) {
      fetchGroups();
    }
  }, [hub.isConnected]);

  useEffect(() => {
      const handleBeforeUnload = () => {
        hub.invoke("LeaveGroupByConnectionId");
      };
  
      window.addEventListener("beforeunload", handleBeforeUnload);
  
      return () => {
        window.removeEventListener("beforeunload", handleBeforeUnload);
      };
    }, [hub]);

  return (
    <div className={styles.wrapper}>
      {loading ? (
        <p className={styles.info_text}>Loading...</p>
      ) : (
        <div>
          {players.length ? (
            <div>
              {players.map((item, index) => {
                return (
                  <RemotePlayerListItem
                    joinGroup={joinGroup}
                    styles={styles}
                    key={index}
                    values={item}
                  />
                );
              })}
            </div>
          ) : (
            <p className={styles.info_text}>ничего нет!</p>
          )}
        </div>
      )}
    </div>
  );
};

export default RemotePlayersList;
