import { atom, useResetRecoilState } from "recoil";

export const controlElementState = atom({
  key: "controlElementState",
  default: {},
});

export const controlElementChangesHistoryState = atom({
  key: "controlElementChangesState",
  default: [],
})

export const presetState = atom({
  key: "presetState",
  default: {},
})

export const useResetAllRecordsStates = () => {
  const resetControlElement = useResetRecoilState(controlElementState);
  const resetControlElementChangesHistory = useResetRecoilState(controlElementChangesHistoryState);

  return () => {
    resetControlElement();
    resetControlElementChangesHistory();
  };
};
