import React, { useState } from "react";
import useServer from "./useServer";
import { useLogger } from "./useLogger";

const EndPoints = {
  SHARED: "get-shared",
  LIKED: "get-liked",
  MY: "get-my",
};

const usePresetsListFetch = () => {
  const { get } = useServer();
  const logger = useLogger();
  const [endPoint, setEndPoint] = useState(EndPoints.SHARED);

  const fetchPresets = async (pageCount, pageNumber) => {
    try {
      logger.log("Fetching presets...");

      const data = await get(`preset/${endPoint}/${pageNumber}/${pageCount}`);

      return data;
    } catch (err) {
      logger.error("Error fetching presets:", err);
    }
  };
  const safeSetEndPoint = (newEndPoint) => {
    if (!Object.values(EndPoints).includes(newEndPoint)) {
      logger.error(`Ошибка: ${newEndPoint} не является допустимым значением`);
      return;
    }
    setEndPoint(newEndPoint);
  };

  return {
    fetchPresets,
    setEndPoint: safeSetEndPoint, 
    endPoint,
    EndPoints,
  };
};

export default usePresetsListFetch;
