import React, { useEffect, useRef } from "react";
import * as Tone from "tone";
import { useLogger } from "./useLogger";

const usePlayer = (
  data,
  handler,
  options = {
    url: "",
    from: null,
    to: null,
  }
) => {
  const prescaler = useRef(100);
  const player = useRef(null);
  const [isPlaying, setIsPlaying] = React.useState(false);
  const logger = useLogger();

  useEffect(() => {
    return () => {
      handleStop();
      if (player.current) {
        player.current.stop();
        player.current.dispose();
        player.current = null;
      }
    };
  }, [options.url, data]);

  const handleFilePlay = async () => {
    try {
      const transport = Tone.getTransport();

      if (!player.current) {
        player.current = new Tone.Player({
          url: options.url,
          onerror: (error) => {
            logger.error("Ошибка загрузки аудио:", error);
            return;
          },
        }).toDestination();
        await player.current.load(options.url);

        if (options.from >= options.to && options.to !== 0) {
          logger.error("Ошибка: from должен быть меньше to");
          return;
        }
        let startParams = [0];
        if (options.from !== 0 && options.to !== 0) {
          startParams = [
            0,
            options.from / prescaler.current,
            options.to / prescaler.current,
          ];
        } else if (options.from !== 0 && options.to === 0) {
          startParams = [0, options.from / prescaler.current];
        } else if (options.from === 0 && options.to !== 0) {
          startParams = [0, 0, options.to / prescaler.current];
        }

        logger.log(options.from, options.to, startParams);
        player.current.sync().start(...startParams);
      }
      await Tone.start();
    } catch (error) {
      logger.error("Ошибка загрузки аудио:", error);
      return;
    }
  };

  const handlePlay = async () => {
    logger.log("start");
    const transport = Tone.getTransport();
    await Tone.start();
    //transport.start();
    data.forEach((item) => {
      transport.schedule(() => {
        logger.log(item.value);
        handler(item);
      }, item.time / 100);
    });
  };

  const handlePause = async () => {
    logger.log("pause");
    const transport = Tone.getTransport();
    transport.pause();
  };

  const handleStop = () => {
    logger.log("stop");
    const transport = Tone.getTransport();
    transport.cancel();
    transport.stop();
    player.current?.dispose();
    player.current = null;
  };

  return {
    play: async () => {
      const promises = [];
      if(options.url){
        promises.push(handleFilePlay());
      }
      promises.push(handlePlay());
      await Promise.all(promises);
      await new Promise(resolve => setTimeout(resolve, 1000));
      Tone.getTransport().start();
      setIsPlaying(true);
    },
    pause: async () => {
      await handlePause();
      setIsPlaying(false);
    },
    stop: async () => {
      await handleStop();
      setIsPlaying(false);
    },
    isPlaying,
  };
};

export default usePlayer;
