import React, { useEffect, useState } from "react";
import ControlElementCreationButton from "./Components/ControlElementCreationButton";
import useServer from "../../hooks/useServer";
import { useParams } from "react-router-dom";
import style from "./ControlElementsBlock.module.scss";
import Playlist from "./Components/Playlist";
import { useRecoilState, useRecoilValue, useResetRecoilState } from "recoil";
import { presetDataState } from "./atoms/presetDataState";
import PresetHeader from "./Components/PresetHeader";
import useHeader from "../../hooks/useHeader";
import AudioLoaderOverlay from "./Components/AudioLoaderOverlay";
import { audioUploadState } from "./atoms/audioUploadState";
import ConditionalRenderer from "../../components/ConditionalRendering/ConditionalRenderer";
import { HubProvider } from "../../contexts/HubContext";
import { useLogger } from "../../hooks/useLogger";

const ControlElementsBlock = ({ presetId = null, preview }) => {
  useHeader(
    <HubProvider>
      <PresetHeader preview={preview} presetId={presetId} />
    </HubProvider>
  );

  const [controlElements, setControlElements] = useRecoilState(presetDataState);
  const { post, get } = useServer();
  const audioUploaded = useRecoilValue(audioUploadState);
  const resetPresetDataState = useResetRecoilState(presetDataState);
  const logger = useLogger();
  const { id } = useParams();

  const getControlElement = async (url, guid) => {
    try {
      const res = await get(url);

      setControlElements((prev) => [...prev, { ...res, guid: guid }]);
    } catch (error) {
      logger.log(error);
    }
  };

  const getControlElementsUrls = async () => {
    try {
      const res = await get(`controlElement/preset-control-elements/${id}`);
      res.forEach(async (item) => {
        await getControlElement(
          item.controlElementUrl,
          item.controlElementGuid
        );
      });
    } catch (error) {
      logger.log(error);
    }
  };

  useEffect(() => {
    logger.log(controlElements);
  }, [controlElements]);

  useEffect(() => {
    getControlElementsUrls();

    return () => {
      resetPresetDataState();
    };
  }, []);

  const onCreate = async (controlElementData) => {
    try {
      const res = await post(
        "controlElement/control-element",
        {
          jsonData: JSON.stringify(controlElementData),
          presetId: id,
        }, // Оставляем JSON.stringify
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      await getControlElement(res.controlElementUrl, res.controlElementGuid);
    } catch (error) {
      logger.error("Error creating control element:", error);
    }
  };

  return (
    <div className={style.wrapper}>
      {audioUploaded && <AudioLoaderOverlay className={style.overlay} />}
      <Playlist preview={preview} className={style} />
      <ConditionalRenderer condition={() => !preview}>
        <ControlElementCreationButton
          className={style.add_button}
          onCreate={onCreate}
        />
      </ConditionalRenderer>
    </div>
  );
};

export default ControlElementsBlock;
