import React, { useEffect, useRef } from "react";
import { Link, Outlet, useNavigate } from "react-router-dom";
import style from "./styles/WorkLayout.module.scss";
import { useRecoilValue } from "recoil";
import useHeader from "../../hooks/useHeader";
import { useAuth } from "../../contexts/AuthProvider";
import { notification } from "antd";
import BreadCrumbs from "../../components/BreadCrumbs/BreadCrumbs";
import { MenuFoldOutlined } from "@ant-design/icons";

const WorkLayout = () => {
  const { getHeader } = useHeader();
  const navigate = useNavigate();
  const [notificationApi, contextHolder] = notification.useNotification();
  const { getJwtLifeTime } = useAuth();

  useEffect(() => {
    const jwtLifeTime = getJwtLifeTime();

    if (!jwtLifeTime) {
      navigate("/");
      return;
    }

    const oneMinuteBeforeExpiry = (jwtLifeTime - 60) * 1000;
    const expiryTime = jwtLifeTime * 1000;
    const showWarning = () => {
      notificationApi.warning({
        placement:"top",
        message: "Скоро кончится сессия, сохраняйся!",
        className: "notification-warning"
      });
    };

    const timeoutWarning = setTimeout(showWarning, oneMinuteBeforeExpiry);
    const timeoutLogout = setTimeout(() => {
      navigate("/");
    }, expiryTime);

    return () => {
      clearTimeout(timeoutWarning);
      clearTimeout(timeoutLogout);
    };
  }, [getJwtLifeTime, navigate, notificationApi]);

  return (
    <div className={style.wrapper}>
      {contextHolder}
      <BreadCrumbs/>
      <header
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {getHeader()}
      </header>
      <main>
        <div className={style.content}>
          <Outlet />
        </div>
      </main>
    </div>
  );
};

export default WorkLayout;
