import React, { useEffect, useState } from "react";
import useServer from "../../hooks/useServer";
import PresetListItem from "../../components/PresetListItem/PresetListItem";
import styles from "./PresetList.module.scss";
import { useInView } from "react-intersection-observer";

const PresetList = ({ customClass }) => {
  const { get } = useServer();
  const [presets, setPresets] = useState([]); // Состояние для хранения полученных пресетов
  const [loading, setLoading] = useState(true); // Состояние для загрузки
  const [page, setPage] = useState(1);
  const { ref, inView } = useInView();

  const fetchPresets = async () => {
    try {
      const data = await get(`/preset/list-info/${page}?pageSize=2`);

      if(!data.length){
        setPresets(prev => [...prev]);
        return;
      }
      
      console.log(presets.length)
      setPresets(prev => [...prev, ...data]);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPresets();
  }, [page]);

  useEffect(() => {
    if (!inView) return;
    setPage((prev) => prev + 1);    
  }, [inView]);

  if (loading) return <div>Loading...</div>; // Отображение индикатора загрузки

  return (
    <div className={`${styles.wrapper} ${styles.customClass}`}>
      <div className={styles.list}>
        {presets.map((x) => (
          <PresetListItem
            styles={styles}
            key={x.id}
            name={x.name}
            id={x.id}
            imageId={x.presetImageUrl}
          />
        ))}
      </div>
      <div
        ref={ref}
        style={{
          marginTop: "10%",
          width: "100%",
          height:"1px",
          background: "none",
        }}
      ></div>
    </div>
  );
};

export default PresetList;
