import React from "react";
import useServer from "./useServer";
import { useLogger } from "./useLogger";

const useControlElemetnSave = () => {
  const { put } = useServer();
  const logger = useLogger();

  const updateControlElement = async (controlElementGuid, newElement) => {
    try {
      const res = await put(
        "/ControlElement/update-control-element",
        {
          controlElementId: controlElementGuid,
          newJson: JSON.stringify(newElement),
        },
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
    } catch (error) {
      logger.error(error);
    }
  };
  return {
    updateControlElement,
  };
};

export default useControlElemetnSave;
