import axios from "axios";
import React, { useContext, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import useServer from "../hooks/useServer";
import axiosInstance from "../utils/axiosInstance";
import { jwtDecode } from "jwt-decode";
import { useLogger } from "../hooks/useLogger";

const AuthContext = React.createContext();

export const AuthProvider = ({ children }) => {
  const logger = useLogger();
  const navigate = useNavigate();
  const { post } = useServer();

  const login = async (username, password) => {
    try {
      const resp = await post(
        "authentication/authenticate-user",
        {
          login: username,
          password: password,
        },
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );
      localStorage.setItem("Authorization", `Bearer ${resp}`);

      navigate("/work");
    } catch (error) {}
  };

  const logout = async () => {
    try {
      const resp = await post("authentication/logout-telegram");
      localStorage.removeItem("Authorization");
    } catch (error) {
      logger.error(error);
    }
  };

  const externalLogin = async (authData, provider = "telegram") => {
    try {
      const resp = await post(`/Authentication/${provider}`, authData, {
        headers: {
          "Content-Type": "application/json",
        },
      });

      localStorage.setItem("Authorization", `Bearer ${resp}`);
      navigate("/work");
    } catch (error) {
      logger.error(error);
    }
  };

  const registrate = async (username, password, email) => {
    try {
      const res = await post(
        "registration/registrate-user",
        {
          login: username,
          password: password,
          email,
        },
        {
          headers: {
            "Content-Type": "application/json",
          },
        }
      );

      localStorage.setItem("Authorization", `Bearer ${res}`);

      navigate("/work");
    } catch (error) {
      logger.error(error);
    }
  };

  const getJwtLifeTime = () => {
    const token = localStorage.getItem("Authorization")?.replace("Bearer ", ""); // Извлеките токен из localStorage
    if (!token) return null;

    try {
      const decoded = jwtDecode(token);
      const exp = decoded.exp; // Ваш exp
      const now = Math.floor(Date.now() / 1000); // Текущее время в секундах
      const timeLeft = exp - now; // Остаток времени в секундах

      return timeLeft;
    } catch (error) {
      logger.error(error);
      return null;
    }
  };

  return (
    <AuthContext.Provider
      value={{ login, externalLogin, registrate, getJwtLifeTime, logout }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  return useContext(AuthContext);
};
