import React, { useEffect } from "react";
import { useLocation, useParams } from "react-router-dom";
import useServer from "../../hooks/useServer";
import style from "./ControlElementHandler.module.scss";
import ChangesChart from "./components/ChangesChart";
import { useRecoilState } from "recoil";
import {
  controlElementChangesHistoryState,
  controlElementState,
  useResetAllRecordsStates,
} from "./atoms/RecordsStates";
import ControlElementHeader from "./components/ControlElementHeader";
import { useLogger } from "../../hooks/useLogger";

const ControlElementHandler = () => {
  const { controlElementGuid, timeIndex } = useParams();
  const { get } = useServer();
  const [controlElementData, setControlElementData] =
    useRecoilState(controlElementState);
  const [changesHistory, setChangesHistory] = useRecoilState(
    controlElementChangesHistoryState
  );
  const resetAllStates = useResetAllRecordsStates();
  const logger = useLogger();

  useEffect(() => {
    //resetAllStates(); // Сбрасываем атомы при изменении controlElementGuid
    const fetchControlElement = async () => {
      try {
        const controlElementDto = await get(
          `/controlElement/control-element/${controlElementGuid}`
        );
        const controlElement = await get(controlElementDto.controlElementUrl);
        setControlElementData(controlElement);
      } catch (error) {
        logger.error(error);
      }
    };

    fetchControlElement();

    return () => {
      setChangesHistory([]);
      setControlElementData({});
    };
  }, [controlElementGuid]); 

  useEffect(() => {
    if (controlElementData?.times?.length) {
      const changes = controlElementData.times[timeIndex]?.changes;
      if (!changes) return;

      setChangesHistory((prev) => [
        ...prev,
        controlElementData.times[timeIndex].changes,
      ]);
    }
  }, [controlElementData]);

  return (
    <div className={style.chart}>
      <ChangesChart />
      <ControlElementHeader></ControlElementHeader>
    </div>
  );
};

export default ControlElementHandler;
