import { Modal } from "antd";
import React from "react";
import style from "./BaseModal.module.scss";

const BaseModal = ({ styles, buttonText, children }) => {
  const [isVisible, setIsVisible] = React.useState(false);

  const showModal = () => {
    setIsVisible(true);
  };

  const hideModal = () => {
    setIsVisible(false);
  };

  return (
    <>
      <Modal
        className={style?.modal}
        onCancel={hideModal}
        open={isVisible}
        onClose={hideModal}
        onOk={hideModal}
        footer={false}
      >
        <div className={style}>{children}</div>
      </Modal>
      <button className={styles?.modal_btn} onClick={showModal}>
        {buttonText}
      </button>
    </>
  );
};

export default BaseModal;
