import { MenuOutlined } from '@ant-design/icons';
import { Dropdown } from 'antd';
import { faChevronRight as arrowDown } from "@fortawesome/free-solid-svg-icons";
import React from 'react';
import { Link } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';

const items = [
  {
    key: '1',
    label: (
      <Link to="/work">Мои пресеты</Link>
    ),
  },
  {
    key: '2',
    label: (
      <Link to="/work/shared-presets">Общие</Link>
    ),
  },
  {
    key: '3',
    label: (
      <Link to="/work/remote-controller">удалённый контроллер</Link>
    ),
  },
];

const NavigationMenu = ({styles}) => {
  return (
    <Dropdown overlayClassName={styles.menu} menu={{ items }} trigger={['click']}>
      <a className={styles.a} onClick={(e) => e.preventDefault()}>
        <FontAwesomeIcon icon={arrowDown} />
      </a>
    </Dropdown>
  );
};

export default NavigationMenu;