import React, { useEffect, useRef, useState } from "react";
import { useLocation, useParams } from "react-router-dom";
import { useRecoilState } from "recoil";
import useServer from "../../../hooks/useServer";
import {
  controlElementChangesHistoryState,
  controlElementState,
  presetState,
} from "../atoms/RecordsStates";
import PlayerModule from "../../../modules/PlayerModule/PlayerModule";
import useControlElemetnSave from "../../../hooks/useControlElemetnSave";
import style from "../ControlElementHandler.module.scss";
import { RedoOutlined, SaveOutlined, UndoOutlined } from "@ant-design/icons";
import NewPlayerModule from "../../../modules/PlayerModule/NewPlayerModule";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faRedo, faSave, faUndo } from "@fortawesome/free-solid-svg-icons";
import { useLogger } from "../../../hooks/useLogger";

const ControlElementHeader = () => {
  const presetId = useLocation().state?.presetId;
  const [url, setUrl] = useState("");
  const [preset, setPreset] = useRecoilState(presetState);
  const [controlElementData, setControlElementData] =
    useRecoilState(controlElementState);
  const [changesHistory, setChangesHistory] = useRecoilState(
    controlElementChangesHistoryState
  );
  const { get } = useServer();
  const { timeIndex } = useParams();
  const { updateControlElement } = useControlElemetnSave();

  const [past, setPast] = useState([]);
  const [future, setFuture] = useState([]);

  const logger = useLogger();

  const shiftTime = (data) => {
    const minTime = Math.min(...data.map((item) => item.time));
    return data.map((item) => ({
      ...item,
      time: item.time - minTime,
    }));
  };

  const removeEmptyArrays = (array) => {
    return array.filter(item => item.length > 0);
  }

  const handleSave = async () => {
    try {
      await updateControlElement(controlElementData.guid, {
        ...controlElementData,
        times: controlElementData.times.with(Number(timeIndex), {
          ...controlElementData.times[Number(timeIndex)],
          changes: [...changesHistory[changesHistory.length - 1]],
        }),
      });
    } catch (error) {
      logger.error(error);
    }
  };

  const handleUndo = () => {
    if (changesHistory.length === 1) return; 

    setChangesHistory((prev) => {
      const newHistory = removeEmptyArrays(prev.slice(0, -1));
      const lastElement = prev[prev.length - 1];
  
      setPast((prevPast) => [...prevPast, lastElement]);
  
      return newHistory;
    });
  };

  const handleRedo = () => {
    if (!past.length) return;

    setPast(prevPast => {
      const lastPast = prevPast[prevPast.length - 1];

      setChangesHistory(prevHistory => {
        const newHistory = removeEmptyArrays([...prevHistory, lastPast]);
        return newHistory;
      })

      return prevPast.slice(0, -1);
    })
  };

  useEffect(() => {
    const fetchPreset = async () => {
      try {
        const preset = await get(`/Preset/get-preset/${presetId}`);
        setPreset(preset);
      } catch (error) {
        logger.error(error);
      }
    };

    fetchPreset();
  }, [presetId]);

  return (
    <div className={style.record_wrapper}>
      <NewPlayerModule data={changesHistory}/>

      <div className={style.undo_control}>
        <button onClick={handleUndo}>
        <FontAwesomeIcon icon={faUndo} />
        </button>
        <button disabled={!changesHistory.length} onClick={handleSave}>
          <FontAwesomeIcon icon={faSave}/>
        </button>
        <button onClick={handleRedo}>
          <FontAwesomeIcon icon={faRedo}/>
        </button>
      </div>
    </div>
  );
};

export default ControlElementHeader;
