import {
  ArrowLeftOutlined,
  ArrowRightOutlined,
  MenuOutlined,
} from "@ant-design/icons";
import { Dropdown, Pagination } from "antd";
import React, { useEffect, useState } from "react";
import styles from "./PaginationModule.module.scss";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { fa8, faAirFreshener, faChevronLeft, faChevronRight, faList12, faListCheck, faMarsAndVenus } from "@fortawesome/free-solid-svg-icons";

const PaginationModule = ({
  pageSize = 10, // Добавил значение по умолчанию
  currentPage,
  totalCount = 0,
  setPages,
}) => {
  const [hasNext, setHasNext] = useState(true);

  useEffect(() => {
    if (totalCount) {
      setHasNext(true);
    } else {
      setHasNext(false);
    }
  }, [totalCount]);

  const items = [
    { key: 10, label: 10 },
    { key: 20, label: 20 },
    { key: 40, label: 40 },
  ];

  return (
    <div className={styles.container}>
      <button
        className={styles.btn}
        disabled={currentPage <= 1}
        onClick={() =>
          setPages((prev) => ({
            ...prev,
            currentPage: prev.currentPage - 1,
          }))
        }
      >
        <FontAwesomeIcon icon={faChevronLeft} />
      </button>

      <button
        className={styles.btn}
        disabled={!hasNext}
        onClick={() =>
          setPages((prev) => ({
            ...prev,
            currentPage: prev.currentPage + 1,
          }))
        }
      >
        <FontAwesomeIcon icon={faChevronRight}/>
      </button>

      <Dropdown
        menu={{
          items,
          onClick: (e) =>
            setPages((prev) => ({ ...prev, presetsOnPage: e.key })),
        }}
        trigger={["click"]}
      >
        <button className={`${styles.btn} ${styles.page_count_btn}`}>
          <FontAwesomeIcon icon={faListCheck}/>
        </button>
      </Dropdown>
    </div>
  );
};

export default PaginationModule;
