import React, { useEffect, useRef, useState } from "react";
import * as echarts from "echarts";
import { Button, Modal, notification } from "antd";
import { EditOutlined, DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import { useRecoilState } from "recoil";
import { presetDataState } from "../atoms/presetDataState";
import { useNavigate, useParams } from "react-router-dom";
import * as Tone from "tone";
import useControlElemetnSave from "../../../hooks/useControlElemetnSave";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCross, faDeleteLeft, faEdit, faTrash, faX } from "@fortawesome/free-solid-svg-icons";
import { useLogger } from "../../../hooks/useLogger";

const Playlist = ({ preview = false, className = null }) => {
  const chartRef = useRef(null);
  const chartInstance = useRef(null);
  const dragging = useRef(false);
  const startX = useRef(0);
  const startY = useRef(0);
  const elementIndex = useRef(null);
  const timeIndexRef = useRef(0);
  const intersecting = useRef(false);
  const midiRef = useRef(null);
  const zoomRef = useRef({
    min: 0,
    max: 1,
  });

  const [notificationApi, contextHolder] = notification.useNotification({
    stack: {
      threshold: true,
    },
  });

  const [data, setData] = useRecoilState(presetDataState);
  const { updateControlElement } = useControlElemetnSave();
  const [recordModalOpen, setRecordModalOpen] = useState(false);
  const [controlElementModalOpen, setControlElementModalOpen] = useState(false);
  const [recordInfo, setRecordInfo] = useState({});
  const logger = useLogger();
  const [controlElementInfo, setControlElementInfo] = useState({});

  const buttonTypeRef = useRef(null);

  const navigate = useNavigate();
  const { id } = useParams();

  const showWarning = () => {
    notificationApi.warning({
      message: "Внимание!",
      description: "Возникло пересечение или неопознанный клик!",
      placement: "top",
      duration: 2,
      className: "notification-warning"
    });
  };

  useEffect(() => {
    if (chartInstance.current) {
      const maxEnd = Math.max(
        ...data.flatMap((task) =>
          task.times.flatMap((timeGroup) =>
            timeGroup.changes?.map((change) => change.time)
          )
        )
      );
      if (navigator.requestMIDIAccess) {
        navigator.requestMIDIAccess().then((access) => {
          const outputs = access.outputs.values();
          const output = outputs.next().value;
          midiRef.current = output;
        });
      }

      chartInstance.current.setOption({
        xAxis: {
          max: maxEnd,
        },
        series: [
          {
            id: "profile",
            data: data.flatMap((task) =>
              task.times.flatMap((timeGroup) => {
                const start = Math.min(
                  ...timeGroup.changes.map((change) => change.time)
                );
                const end = Math.max(
                  ...timeGroup.changes.map((change) => change.time)
                );
                return [[start, task.name, end]];
              })
            ),
          },
          {
            id: "ce",
            data: [...data.map((i) => i.name)],
          },
        ],
      });
    }
  }, [data]);

  useEffect(() => {
    chartInstance.current = echarts.init(chartRef.current);

    const option = {
      tooltip: {
        trigger: "item",
        formatter: function (params) {
          const task = params.data[4];
          if (params.seriesId === "profile")
            return `
            <div>
              <strong>Элемент:</strong> ${task?.name}<br>
              <strong>Начало:</strong> ${task?.start} мс<br>
              <strong>Конец:</strong> ${task?.end} мс<br>
            </div>
          `;
        },
      },
      dataZoom: [
        {
          type: "slider",
          filterMode: "none",
          moveOnMouseMove: false,
          xAxisIndex: [0],
          start: zoomRef.current.min,
          end: zoomRef.current.max,
        },
        {
          type: "inside",
          moveOnMouseMove: false,
          filterMode: "none",
          xAxisIndex: [0],
          start: zoomRef.current.min,
          end: zoomRef.current.max,
        },
      ],
      xAxis: {
        type: "value",
        min: 0,
        max: Math.max(
          ...data.flatMap((task) =>
            task.times.flatMap((timeGroup) =>
              timeGroup.changes.map((change) => change.time)
            )
          )
        ),
        axisLabel: {
          formatter: (value) => `${value} мс`,
        },
      },
      yAxis: {
        type: "category",
        axisTick: { show: false },
        splitLine: { show: false },
        axisLine: { show: false },
        axisLabel: { show: false },
        data: data.map((task) => task.name), // Список категорий (задач)
        inverse: true, // Инвертированная ось Y
        max: data.length, // Ось Y фиксирована по количеству элементов
        min: 0, // Начало оси Y
        interval: 1, // Каждая категория будет иметь одинаковое расстояние
      },

      series: [
        {
          id: "profile",
          type: "custom",
          clip: false,
          renderItem: function (params, api) {
            const categoryIndex = api.value(1);
            const start = api.coord([api.value(0), categoryIndex]);
            const end = api.coord([api.value(2), categoryIndex]);
            const endPoint = api.value(2);
            const height = api.size([0, 1])[1] * 0.6;

            const [x, y] = chartInstance.current.convertFromPixel("grid", [
              start[0],
              end[0] - start[0],
            ]);
            return {
              type: "group",
              children: [
                {
                  type: "rect",
                  shape: {
                    x: start[0],
                    y: start[1] - height / 2,
                    width: end[0] - start[0],
                    height: height,
                  },
                  style: {
                    fill: {
                      type: "linear",
                      x: 0,
                      y: 0,
                      x2: 1,
                      y2: 0,
                      colorStops: [
                        { offset: 0, color: "#6fffe9" }, // Начальный цвет
                        { offset: 1, color: "#3CABFF" }, // Конечный цвет
                      ],
                    },
                    stroke: "#6fffe9", // Цвет рамки (черный)
                    lineWidth: 2, // Толщина рамки
                  },
                },
                {
                  type: "text",
                  style: {
                    x: start[0],
                    y: start[1] - height * 0.1,
                    text: `c ${Math.round(x)} по ${endPoint}`, // Имя задачи
                    textVerticalAlign: "bottom",
                    textAlign: "start",
                    textFill: "#000", // Цвет текста
                    fontSize: 14, // Увеличенный размер шрифта
                    fontWeight: "bold", // Жирный шрифт
                  },
                },
                {
                  type: "line",
                },
              ],
            };
          },
          encode: {
            x: [0, 2],
            y: 1,
          },
          data: data.flatMap((task, taskIndex) =>
            task.times.flatMap((timeGroup, timesIndex) => {
              const start = Math.min(
                ...timeGroup.changes.map((change) => change.time)
              );
              const end = Math.max(
                ...timeGroup.changes.map((change) => change.time)
              );
              return [
                [
                  start,
                  task.name,
                  end,
                  timeGroup.changes[timesIndex],
                  {
                    name: task.name,
                    start: start,
                    end: end,
                    timesIndex: timesIndex,
                    taskIndex: taskIndex,
                    guid: task.guid,
                  },
                ],
              ];
            })
          ),
        },
        {
          id: "ce",
          type: "custom",
          renderItem: (params, api) => {
            const y = api.coord([0, api.value(0)])[1];
            if (y < params.coordSys.y + 5) {
              return;
            }

            const text = data[api.value(0)].name;
            const maxCharsPerLine = 10;
            const lines = [];
            for (let i = 0; i < text.length; i += maxCharsPerLine) {
              lines.push(text.substring(i, i + maxCharsPerLine));
            }

            const textWidth = Math.min(...lines.map((line) => line.length)) * 8;
            const rectWidth = textWidth + 40;

            // Вычисляем высоту так же, как в profile
            const height = api.size([0, 1])[1] * 0.6;

            return {
              type: "group",
              position: [10, y],
              children: [
                {
                  type: "rect",
                  shape: {
                    x: 0,
                    y: -height / 2, // Центрируем
                    width: rectWidth,
                    height: height, // Делаем высоту такой же
                  },
                  style: {
                    fill: "#368c6c",
                  },
                },
                ...lines.map((line, index) => ({
                  type: "text",
                  style: {
                    x: 24,
                    y: -height / 2 + 20 + index * 20,
                    text: line,
                    textVerticalAlign: "bottom",
                    textAlign: "start",
                    textFill: "#fff",
                  },
                })),
              ],
            };
          },
          encode: {
            y: 0, // Индекс оси Y, который используется для отображения задач
          },
          data: data.flatMap((task, taskIndex) => [
            [
              task.name,
              {
                name: task.name,
                taskIndex: taskIndex,
                ccType: task.ccType,
              },
            ],
          ]),
          // Пример: третье значение — максимальное время для задачи
        },
      ],
    };

    chartInstance.current.setOption(option);
    const zr = chartInstance.current.getZr();

    const handleMouseDown = (e) => {
      if (preview) return;

      buttonTypeRef.current = e.event.button;
      const pointInPixel = [e.offsetX, e.offsetY];

      for (let i = 0; i < zr.storage.getDisplayList().length; i++) {
        const element = zr.storage.getDisplayList()[i];
        if (element.contain(pointInPixel[0], pointInPixel[1])) {
          dragging.current = true;
          startX.current = e.offsetX;
          startY.current = e.offsetY;
          elementIndex.current = i;

          const [x, y] = chartInstance.current.convertFromPixel("grid", [
            pointInPixel[0],
            pointInPixel[1],
          ]);

          const taskIndex = Math.round(y);
          const selectedTask = data[taskIndex];

          if (selectedTask) {
            timeIndexRef.current = selectedTask.times.findIndex((timeGroup) => {
              const start = Math.min(
                ...timeGroup.changes.map((change) => change.time)
              );
              const end = Math.max(
                ...timeGroup.changes.map((change) => change.time)
              );
              return x >= start && x <= end;
            });
          }

          break;
        }
      }
    };

    const handleMouseMove = (e) => {
      if (preview) return;

      if (
        dragging.current &&
        elementIndex.current !== null &&
        buttonTypeRef.current === 0
      ) {
        const dx = e.offsetX - startX.current;

        const element = zr.storage.getDisplayList()[elementIndex.current];
        if (element.type !== "rect") return;
        if (element && element.shape) {
          const newX = Math.max(element.shape.x + dx, 0);

          if (newX >= 0) {
            element.shape.x = newX;
            element.dirty();
            zr.refresh();
            startX.current = e.offsetX;

            const displayList = zr.storage
              .getDisplayList()
              .filter((el) => el.type === "rect");

            intersecting.current = false; // Сброс состояния пересечения

            for (let i = 0; i < displayList.length; i++) {
              const otherElement = displayList[i];

              if (otherElement.id === element.id) continue;

              const elementStart = element.shape.x;
              const elementEnd = element.shape.x + element.shape.width;
              const otherStart = otherElement.shape.x;
              const otherEnd = otherElement.shape.x + otherElement.shape.width;

              const [elementCoordsStart, y] =
                chartInstance.current.convertFromPixel("grid", [
                  elementStart,
                  element.shape.y,
                ]);
              if (
                (elementStart < otherEnd &&
                  elementEnd > otherStart &&
                  Math.round(element.shape.y) ===
                    Math.round(otherElement.shape.y)) ||
                elementCoordsStart < 0
              ) {
                intersecting.current = true;
                break;
              }
            }
          }
        }
      }
    };

    const handleMouseUp = () => {
      if (preview) return;

      buttonTypeRef.current = null;
      if (
        dragging.current &&
        elementIndex.current !== null &&
        timeIndexRef.current !== -1
      ) {
        if (intersecting.current) {
          showWarning();
          elementIndex.current = null;
          dragging.current = false;
          intersecting.current = false;

          chartInstance.current.setOption({
            series: [
              {
                id: "profile",
                data: data.flatMap((task) =>
                  task.times.flatMap((timeGroup) => {
                    const start = Math.min(
                      ...timeGroup.changes.map((change) => change.time)
                    );
                    const end = Math.max(
                      ...timeGroup.changes.map((change) => change.time)
                    );
                    return [[start, task.name, end]];
                  })
                ),
              },
            ],
          });
          return;
        }

        const element = zr.storage.getDisplayList()[elementIndex.current];

        if (element && element.shape) {
          const [x, y] = chartInstance.current.convertFromPixel("grid", [
            element.shape.x,
            element.shape.y,
          ]);

          const width = element.shape.width;
          const [endX] = chartInstance.current.convertFromPixel("grid", [
            element.shape.x + width,
            element.shape.y,
          ]);

          const taskIndex = Math.round(y);
          const selectedTask = data[taskIndex];

          if (selectedTask && timeIndexRef.current !== -1) {
            const timeGroup = selectedTask.times[timeIndexRef.current];
            const updatedTimeGroup = timeGroup.changes.map((change) => ({
              ...change,
              time:
                change.time +
                (Math.round(x) -
                  Math.min(...timeGroup.changes.map((c) => c.time))),
            }));
            setData((prevData) => {
              const updatedData = prevData.map((task, index) => {
                if (index === taskIndex) {
                  const updatedTimes = task.times.map(
                    (timeGroup, timeIndex) => {
                      if (timeIndex === timeIndexRef.current) {
                        return {
                          ...timeGroup,
                          changes: updatedTimeGroup,
                        };
                      }
                      return timeGroup;
                    }
                  );
                  const newTask = { ...task, times: updatedTimes };
                  updateControlElement(task.guid, newTask).then();
                  return newTask;
                }

                return task;
              });
              return updatedData;
            });
          }

          chartInstance.current.setOption({
            series: [
              {
                id: "profile",
                data: data.flatMap((task) =>
                  task.times.flatMap((timeGroup) => {
                    const start = Math.min(
                      ...timeGroup.changes.map((change) => change.time)
                    );
                    const end = Math.max(
                      ...timeGroup.changes.map((change) => change.time)
                    );
                    return [[start, task.name, end]];
                  })
                ),
              },
            ],
          });
        }
      }
      // timeIndexRef.current = -1;
      elementIndex.current = null;
      dragging.current = false;
    };

    const handleMouseOut = () => {
      dragging.current = false;
      elementIndex.current = null;
      timeIndexRef.current = -1;
    };

    const handleRecordClick = (params) => {
      if (preview) return;
      const paramsData = params.data[4];

      setRecordInfo((prev) => {
        return {
          ...prev,
          name: paramsData?.name,
          end: paramsData?.end,
          start: paramsData?.start,
          timesIndex: paramsData?.timesIndex,
          guid: paramsData?.guid,
        };
      });
      setRecordModalOpen(true);
    };

    const handleControlElementClick = (params) => {
      if (preview) return;

      const data = params.data[1];
      setControlElementInfo({
        name: data.name,
        taskIndex: data.taskIndex,
      });

      setControlElementModalOpen(true);
    };

    zr.on("mousedown", (e) => handleMouseDown(e));
    zr.on("mousemove", handleMouseMove);
    zr.on("mouseup", handleMouseUp);
    zr.on("mouseout", handleMouseOut);
    zr.on("contextmenu", (e) => {
      e.event.stopPropagation();
      e.event.preventDefault();
    });
    chartInstance.current.on(
      "contextmenu",
      { seriesId: "profile" },
      handleRecordClick
    );
    chartInstance.current.on(
      "contextmenu",
      { seriesId: "ce" },
      handleControlElementClick
    );
    chartInstance.current.on("dataZoom", (event) => {
      const zoom = event.batch?.[0] || event; // Получаем данные о зуме
      if (zoom) {
        zoomRef.current = { min: zoom.start, max: zoom.end }; // Обновляем состояние
      }
    });
    return () => {
      zr.off("mousedown", handleMouseDown);
      zr.off("mousemove", handleMouseMove);
      zr.off("mouseup", handleMouseUp);
      zr.off("mouseout", handleMouseOut);
      zr.off("dblclick", handleRecordClick);
      chartInstance.current.off("contextmenu", handleRecordClick);
      chartInstance.current.dispose();
      chartInstance.current.off("dataZoom");
    };
  }, [data]);

  const handleDelete = () => {
    if (recordInfo.guid) {
      setData((prevData) => {
        const updatedData = prevData.map((task) => {
          if (task.guid === recordInfo.guid) {
            // Удаляем timeGroup по индексу timesIndex
            const updatedTimes = task.times.filter(
              (timeGroup, index) => index !== recordInfo.timesIndex
            );
            return { ...task, times: updatedTimes };
          }
          return task;
        });

        // Обновляем элемент в базе данных
        const taskToUpdate = updatedData.find(
          (task) => task.guid === recordInfo.guid
        );
        if (taskToUpdate) {
          updateControlElement(taskToUpdate.guid, taskToUpdate).then();
        }

        return updatedData;
      });

      // Закрываем модальное окно после удаления
      setRecordModalOpen(false);
    }
  };

  return (
    <>
      {contextHolder}
      <div ref={chartRef} className={className.bb} />
      <Modal
        closeIcon={<FontAwesomeIcon className={className.cross} icon={faX}/>}
        className={className.modal}
        footer={false}
        open={recordModalOpen}
        onCancel={() => setRecordModalOpen(false)}
      >
        <div
          className={className.modal_content}
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-around",
          }}
        >
          <h1>
            {recordInfo.start} - {recordInfo.end} мс
          </h1>
          <button
            type="primary"
            className={className.edit_btn}
            onClick={() => {
              navigate(
                `/work/preset/${id}/control-element/${recordInfo.timesIndex}/${recordInfo.guid}`,
                {
                  state: { presetId: id },
                }
              );
            }}
          >
            <FontAwesomeIcon icon={faEdit}/>
            Редактировать
          </button>
          <button
            className={className.delete_btn}
            style={{
              display: "block",
              background: "#c1121f",
            }}
            type="danger"
            icon={<DeleteOutlined />}
            onClick={handleDelete}
          >
           <FontAwesomeIcon icon={faTrash}/> Удалить
          </button>
        </div>
      </Modal>

      <Modal
      closeIcon={<FontAwesomeIcon className={className.cross} icon={faX}/>}
        className={className.modal}
        open={controlElementModalOpen}
        footer={false}
        onCancel={() => setControlElementModalOpen(false)}
      >
        <div
          className={className.modal_content}
          style={{
            width: "100%",
            height: "100%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
          }}
        >
          <h1>
            CC#{data[controlElementInfo?.taskIndex]?.ccType}{" "}
            {data[controlElementInfo?.taskIndex]?.name}
          </h1>
          <button
            className={className.learn_btn}
            onClick={() => {
              midiRef.current?.send([
                0xb0,
                data[controlElementInfo?.taskIndex]?.ccType,
                1,
              ]);
            }}
          >
            Lern
          </button>
          <button
            className={className.add_btn}
            onClick={() => {
              if (
                controlElementInfo?.taskIndex === null ||
                controlElementInfo?.taskIndex === undefined
              )
                return;

              const taskIndex = controlElementInfo.taskIndex;
              const presetToChange = data[taskIndex];
              const maxTime = presetToChange.times?.length
                ? Math.max(
                    ...presetToChange.times.flatMap((timeGroup) =>
                      timeGroup.changes.map((change) => change.time)
                    )
                  )
                : 0;

              const newTimeGroup = {
                changes: [
                  { value: 0, time: maxTime },
                  { value: 0, time: maxTime + 10 },
                ],
              };

              setData((prev) => {
                try {
                  const updatedData = [...prev];
                  updatedData[taskIndex] = {
                    ...presetToChange,
                    times: [...presetToChange.times, newTimeGroup],
                  };
                  updateControlElement(
                    presetToChange.guid,
                    updatedData[taskIndex]
                  ).then();
                  return updatedData;
                } catch (error) {
                  logger.log("ошибка создания элемента");
                }
              });
            }}
            type="primary"
            style={{ backgroundColor: "pink", borderColor: "pink" }}
            icon={<PlusOutlined />}
          >
            Добавить
          </button>
        </div>
      </Modal>
    </>
  );
};

export default Playlist;
