import React, { useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";
import styles from "./BreadCrumbs.module.scss";
import { useBreadCrumbs } from "../../utils/CrumbsProvider";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faChevronRight as arrowRight } from "@fortawesome/free-solid-svg-icons";
import { Button, Dropdown, Menu } from "antd";
import NavigationMenu from "./NavigationMenu";

const BreadCrumbs = () => {
  const location = useLocation();
  const { breadCrumbs } = useBreadCrumbs();
  const [filteredCrumbs, setFilteredCrumbs] = useState([]);

  useEffect(() => {
    const matchPath = (crumbPath, currentPath) => {
      const regexPath = crumbPath.replace(/:\w+/g, "[^/]+");
      const regex = new RegExp(`^${regexPath}`);
      return regex.test(currentPath);
    };

    setFilteredCrumbs(
      breadCrumbs.filter(
        (bc) =>
          location.pathname.startsWith(bc.path) ||
          matchPath(bc.path, location.pathname)
      )
    );
  }, [breadCrumbs, location.pathname]);

  const getActualPath = (breadcrumbPath) => {
    const pathSegments = location.pathname.split("/");
    const breadcrumbSegments = breadcrumbPath.split("/");

    return breadcrumbSegments
      .map((segment, index) =>
        segment.startsWith(":") ? pathSegments[index] : segment
      )
      .join("/");
  };
  return (
    <div className={styles.breadcrumbs}>
      {filteredCrumbs.map((bc, index) => {
        const actualPath = getActualPath(bc.path);
        return (
          <React.Fragment key={bc.path}>
            <span className={styles.crumb_span}>
              <Link className={styles.crumb_link} to={actualPath}>
                {bc.crumb}
              </Link>
              {index < filteredCrumbs.length - 1 && (
                <FontAwesomeIcon className={styles.period} icon={arrowRight} />
              )}
            </span>
          </React.Fragment>
        );
      })}
      <NavigationMenu styles={styles}/>
    </div>
  );
};

export default BreadCrumbs;
