import React, { createContext, useContext, useEffect } from "react";
import { atom, useRecoilState } from "recoil";

const BreadCrumbsContext = createContext({
  breadCrumbs: [],
  setBreadCrumbs: () => {},
});

const breadCrumbsState = atom({
    key: 'breadCrumbs',
    default: [],
})

export const useBreadCrumbs = () => useContext(BreadCrumbsContext);

const CrumbsProvider = ({ children }) => {
  const [breadCrumbs, setBreadCrumbs] = useRecoilState(breadCrumbsState);
  /**
   * Рекурсивная функция для сбора путей из дочерних элементов.
   * Если маршрут вложенный, формируется полный путь, объединяя родительский и текущий.
   *
   * @param {React.ReactNode} childElements - дочерние элементы
   * @param {string} parentPath - родительский путь (по умолчанию пустая строка)
   * @returns {string[]} Массив полных путей
   */
  const extractPaths = (childElements, parentPath = "") => {
    let paths = [];

    React.Children.forEach(childElements, (child) => {
      if (React.isValidElement(child)) {
        let currentPath = parentPath;

        if (child.props?.path) {
          // Если путь начинается с "/", считаем его абсолютным
          if (child.props.path.startsWith("/")) {
            currentPath = child.props.path;
          } else {
            // Если родительский путь равен "/" — не добавляем лишний слеш
            currentPath =
              parentPath === "/" || parentPath === ""
                ? `/${child.props.path}`
                : `${parentPath}/${child.props.path}`;
          }
        } else if (child.props.index) {
          // Для индексного маршрута используем родительский путь
          currentPath = parentPath;
        }

        // Если текущий путь не пустой, добавляем его
        if (currentPath && child.props?.crumb) {
          paths.push({
            crumb: child.props?.crumb,
            path: currentPath,
          });
        }

        // Если есть вложенные маршруты, рекурсивно их обрабатываем,
        // передавая текущий путь как родительский
        if (child.props.children) {
          paths = paths.concat(extractPaths(child.props.children, currentPath));
        }
      }
    });

    return paths;
  };

  useEffect(() => {
    const allPaths = extractPaths(children);
    setBreadCrumbs(allPaths);
  }, [children]);

  return (
    <BreadCrumbsContext.Provider value={{ breadCrumbs, setBreadCrumbs }}>
      {children}
    </BreadCrumbsContext.Provider>
  );
};

export default CrumbsProvider;
