import React from "react";
import styles from "../ControlElementsBlock.module.scss";
import { Spin } from "antd";

const AudioLoaderOverlay = ({ className }) => {
  return (
    <div className={className}>
      <div>
        <Spin size="large" />
        <p>Загружаем аудио трек...</p>
      </div>
    </div>
  );
};

export default AudioLoaderOverlay;
