import React, { forwardRef, useEffect, useRef } from "react";
import { remoteControlState } from "../atoms/RemoteControlState";
import { useHubContext } from "../../../contexts/HubContext";
import * as Tone from "tone";

const WithRemoteRecordControl = (Component) => {
  const WrappedComponent = forwardRef((props, ref) => {
    const innerRef = useRef(null);
    const componentRef = ref || innerRef;
    const { hub } = useHubContext();

    const handleReceivePlayerStateChange = async (playerState) => {
      try {
        switch (playerState.remotePlayerState) {
          case 1: {
            componentRef.current?.play();
            break;
          }
          case 2: {
            componentRef.current?.pause();
            break;
          }
          case 3: {
            componentRef.current?.stop();
            break;
          }
          default: {
            console.warn(
              `Unexpected remote player state: ${playerState.remotePlayerState}`
            );
          }
        }
      } catch (error) {
        console.error(error);
      }
    };

    useEffect(() => {
      if (hub.isConnected) {
        hub.on("ReceivePlayerStateChange", handleReceivePlayerStateChange);
      }
    }, [hub.isConnected]);

    return <Component {...props} ref={componentRef} />;
  });

  return WrappedComponent;
};

export default WithRemoteRecordControl;
